export const c12Phy2HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  \n  <!-- QUICK GLOSSARY CARD -->\n  <div style=\"background: rgba(142, 45, 226, 0.05); border: 1.5px solid #8E2DE2; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #8E2DE2; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary &amp; Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #8E2DE2; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Concepts &amp; Key Definitions &bull; Unit II: Current Electricity</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 4px;'>1. Electric Current (I):</b>\n        <span style=\"color: #FFFFFF;\">Rate of flow of electric charge across any cross-section: I = dq/dt [Ampere A, Dimensions: [A]]. Scalar quantity.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 4px;'>2. Drift Velocity (v<sub>d</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Average velocity with which free electrons drift opposite to applied electric field: v<sub>d</sub> = (e E &#964;)/m &approx; 10<sup>-4</sup> m s<sup>-1</sup>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 4px;'>3. Electron Mobility (&#956;):</b>\n        <span style=\"color: #FFFFFF;\">Magnitude of drift velocity per unit electric field: &#956; = v<sub>d</sub> / E = (e &#964;)/m [m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup>]. Always positive.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 4px;'>4. Resistivity (&#961;) &amp; Conductivity (&#963;):</b>\n        <span style=\"color: #FFFFFF;\">Intrinsic property &#961; = m / (n e<sup>2</sup> &#964;) [&Omega; m], &#963; = 1/&#961; = (n e<sup>2</sup> &#964;)/m [S m<sup>-1</sup>]. Independent of dimensions.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 4px;'>5. Electromotive Force (EMF, &#949;) &amp; Internal Resistance (r):</b>\n        <span style=\"color: #FFFFFF;\">Maximum potential difference across open-circuit cell terminals. Terminal voltage during discharge: V = &#949; - I r.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 4px;'>6. Wheatstone Bridge Condition:</b>\n        <span style=\"color: #FFFFFF;\">When galvanometer current I<sub>g</sub> = 0 (null deflection), the ratio of bridge arms satisfies P / Q = R / S.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 25px;\">1. Electric Current, Flow of Electric Charges in Metallic Conductors, Drift Velocity &amp; Mobility</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(142, 45, 226, 0.4); border-left: 5px solid #8E2DE2; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #8E2DE2; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Drift Velocity (v<sub>d</sub>)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Average velocity with which free electrons get drifted towards the positive terminal of a conductor under applied electric field: <b>v<sub>d</sub> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e <b>E</b></span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> &tau;</b>.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">m s<sup>-1</sup></span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>0</sup> L<sup>1</sup> T<sup>-1</sup>]</span></span>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(142, 45, 226, 0.4); border-left: 5px solid #8E2DE2; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #8E2DE2; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Electron Mobility (&mu;)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Magnitude of drift velocity acquired per unit applied electric field: <b>&mu; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>d</sub></span><span style=\"padding: 0 2px; display: inline-block;\">E</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e &tau;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup></span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>-1</sup> L<sup>0</sup> T<sup>2</sup> A<sup>1</sup>]</span></span>\n    </div>\n  </div>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #38BDF8; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #38BDF8; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: Drift vs Thermal Velocity Analogy</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Imagine a huge swarm of bees buzzing wildly at 100 km/h in every random direction (thermal velocity ~10<sup>5</sup> m/s). When a gentle breeze starts blowing, the entire swarm slowly drifts forward at 1 cm/s (drift velocity ~10<sup>-4</sup> m/s). That gentle forward drift is electric current!</div>\n  </div>\n  <div style=\"background: rgba(220, 38, 38, 0.1); border: 1.2px solid rgba(239, 68, 68, 0.4); border-left: 5px solid #EF4444; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #F87171; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">⚠️ BOARD EXAM TRAP &amp; CONCEPTUAL PITFALL: Why Light Turns On Instantly Despite Slow Drift Velocity</div>\n    <div style=\"color: #FCA5A5; font-size: 14.5px; line-height: 1.6;\">Free electrons drift at just ~0.1 mm/s. But when you flip a switch, the electric field travels through the wire at nearly the speed of light (~3 &times; 10<sup>8</sup> m/s), setting all 10<sup>28</sup> electrons per m<sup>3</sup> into motion simultaneously across the entire circuit!</div>\n  </div>\n  \n  <p>Current electricity is the dynamic branch of physics dealing with charges in steady motion. In electrostatics, charges reside at rest on conductors in electrostatic equilibrium where the internal electric field is zero. However, when an external electric field or potential difference is maintained across the ends of a metallic conductor by a battery or external power source, electric charges experience continuous electrostatic forces, establishing a macroscopic continuous electric current.</p>\n\n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Current (I)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric current across any cross-sectional area of a conductor is defined as the net rate of flow of electric charge passing through that area per unit time: I = dq / dt. In steady state, I = q / t. SI Unit: Ampere (A) = 1 Coulomb per second (C s<sup>-1</sup>). Dimensional Formula: [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup> A<sup>1</sup>]. Electric current is a <b>scalar quantity</b> because it obeys ordinary scalar algebraic laws of addition rather than vector addition laws.</div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(i) Flow of Charges in Metallic Conductors &amp; Microscopic Electron Dynamics</h3>\n  <p>In solid metallic conductors (such as copper, aluminium, and silver), positive atomic ions are rigidly locked in crystal lattice sites, while valence electrons detach to form an abundant &quot;free electron gas&quot; with enormous number density (n &approx; 8.5 &times; 10<sup>28</sup> free electrons per m<sup>3</sup> in copper). In the absence of an applied electric field (thermal equilibrium):</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Thermal Random Motion:</b> Free electrons move randomly in all possible directions with high thermal speeds (u<sub>rms</sub> = &radic;(3 k<sub>B</sub> T / m) &approx; 10<sup>5</sup> to 10<sup>6</sup> m s<sup>-1</sup> at room temperature 300 K).</li>\n    <li><b>Zero Net Thermal Current:</b> Because velocity vectors are completely random in three dimensions, the average thermal velocity of all electrons across any cross-section is strictly zero: <b>u<sub>avg</sub></b> = (1/N) &Sigma; <b>u<sub>i</sub></b> = 0. Hence, an isolated metal wire carries zero electric current.</li>\n  </ul>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(ii) Drift Velocity (v<sub>d</sub>) &amp; Relaxation Time (&#964;)</h3>\n  <p>When a potential difference V is applied across a conductor of length L, a uniform internal electric field <b>E</b> = V / L is established. Each free electron of mass m and charge -e experiences an electrostatic force <b>F</b> = -e <b>E</b>, acquiring an acceleration <b>a</b> = -e <b>E</b> / m directed opposite to <b>E</b>.</p>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Drift Velocity (v<sub>d</sub>) &amp; Relaxation Time (&#964;)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\"><b>Drift Velocity (v<sub>d</sub>)</b> is the small, constant average velocity with which free electrons drift slowly through a metallic conductor in the direction opposite to the applied external electric field. Typical magnitude: 10<sup>-4</sup> m s<sup>-1</sup> (a few tenths of a millimeter per second).<br><br><b>Relaxation Time (&#964;)</b> is the average time interval elapsed between two successive collisions of a drifting free electron with the heavy positive metal lattice ions. Typical value for copper at room temperature: &#964; &approx; 10<sup>-14</sup> s.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(142, 45, 226, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(142, 45, 226, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Drift Velocity Formula\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      <b>1. Acceleration of an Electron:</b><br>\n      Under electric field <b>E</b>, acceleration <b>a</b> = <b>F</b> / m = (-e <b>E</b>) / m.<br><br>\n      <b>2. Velocity of the i-th Electron:</b><br>\n      If the i-th electron had initial random thermal velocity <b>u<sub>i</sub></b> just after its last collision and time elapsed since that collision is t<sub>i</sub>:<br>\n      <b>v<sub>i</sub></b> = <b>u<sub>i</sub></b> + <b>a</b> t<sub>i</sub> = <b>u<sub>i</sub></b> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e <b>E</b></span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> t<sub>i</sub>.<br><br>\n      <b>3. Average Velocity (Drift Velocity <b>v<sub>d</sub></b>):</b><br>\n      <b>v<sub>d</sub></b> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">N</span></span> &Sigma; <b>v<sub>i</sub></b> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">N</span></span> &Sigma; <b>u<sub>i</sub></b> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e <b>E</b></span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">N</span></span> &Sigma; t<sub>i</sub>].<br><br>\n      Since <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">N</span></span> &Sigma; <b>u<sub>i</sub></b> = 0 (zero net thermal velocity) and <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">N</span></span> &Sigma; t<sub>i</sub> = &#964; (average relaxation time):<br><br>\n      <div style=\"background: rgba(0,0,0,0.35); border: 1px solid #8E2DE2; border-radius: 6px; padding: 10px; text-align: center; color: #FFFFFF; font-size: 16px;\">\n        <b><b>v<sub>d</sub></b> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e <b>E</b> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> &nbsp;|&nbsp; Magnitude: v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span></b>\n      </div>\n    </div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(iii) Derivation of Relation Between Electric Current and Drift Velocity</h3>\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(142, 45, 226, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(142, 45, 226, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Relation Between Electric Current &amp; Drift Velocity (I = n e A v<sub>d</sub>)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      <b>1. Geometry:</b> Consider a metallic conductor of length L, uniform cross-sectional area A, and free electron number density n (electrons per m<sup>3</sup>).<br><br>\n      <b>2. Total Number of Free Electrons in Conductor:</b><br>\n      N = n &times; Volume = n &times; (A &times; L).<br><br>\n      <b>3. Total Mobile Charge in Conductor:</b><br>\n      q = N &times; e = (n A L) e.<br><br>\n      <b>4. Transit Time across Conductor:</b><br>\n      Time taken by an electron to drift through entire length L with drift speed v<sub>d</sub> is t = L / v<sub>d</sub>.<br><br>\n      <b>5. Resulting Electric Current:</b><br>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span><span style=\"padding: 0 2px; display: inline-block;\">t</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n A L e</span><span style=\"padding: 0 2px; display: inline-block;\">L / v<sub>d</sub></span></span> = <b>n e A v<sub>d</sub></b>.<br><br>\n      <div style=\"background: rgba(0,0,0,0.35); border: 1px solid #8E2DE2; border-radius: 6px; padding: 10px; text-align: center; color: #FFFFFF; font-size: 16px;\">\n        <b>I = n e A v<sub>d</sub> &nbsp;|&nbsp; Current Density: j = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">I</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span> = n e v<sub>d</sub></b>\n      </div>\n    </div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(iv) Electron Mobility (&#956;)</h3>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Mobility (&#956;)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Mobility of a charge carrier is defined as the magnitude of its drift velocity per unit electric field applied: &#956; = v<sub>d</sub> / E = (e &#964;) / m. SI Unit: m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup> (or m<sup>2</sup> N<sup>-1</sup> C s<sup>-1</sup>). Dimensional Formula: [M<sup>-1</sup> L<sup>0</sup> T<sup>2</sup> A<sup>1</sup>]. Mobility is always a positive scalar physical quantity. Current in terms of mobility: I = n e A &#956; E.</div>\n  </div>\n\n  <div style=\"background: rgba(255, 193, 7, 0.08); border-left: 4.5px solid #FFC107; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD54F; font-size: 16.5px; display: block; margin-bottom: 6px;\">⚠️ BOARD EXAM FOCUS &amp; COMMON TRAPS: Why do Electric Bulbs Glow Instantly if Drift Speed is so Tiny (~10<sup>-4</sup> m s<sup>-1</sup>)?</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Although individual free electrons drift at a tiny speed of &approx; 0.1 mm s<sup>-1</sup>, closing the switch establishes an electromagnetic wave/electric field throughout the entire closed circuit almost instantaneously at the speed of light in vacuum (c &approx; 3 &times; 10<sup>8</sup> m s<sup>-1</sup>). Free electrons present throughout all points of the conductor begin drifting simultaneously at the very same instant, lighting the bulb immediately without having to wait for electrons to travel from the switch.</div>\n  </div>\n\n  <div style=\"background: rgba(0, 229, 255, 0.05); border: 1.2px solid rgba(0, 229, 255, 0.3); border-radius: 10px; padding: 16px; margin: 20px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 6px;\">📝 SOLVED BOARD EXAMPLE 1:</b>\n    <div style=\"color: #FFFFFF; font-weight: 500; font-size: 15.5px; margin-bottom: 10px;\">A copper wire of cross-sectional area 1.0 &times; 10<sup>-7</sup> m<sup>2</sup> carries a steady current of 1.5 A. Assuming free electron density of copper is 8.5 &times; 10<sup>28</sup> m<sup>-3</sup>, calculate: (a) Current density in the wire, (b) Drift velocity of free electrons. (Take e = 1.6 &times; 10<sup>-19</sup> C).</div>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3px solid #00E5FF; padding: 10px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15px; line-height: 1.6;\">\n      <b style=\"color: #00E5FF;\">Step-by-Step Solution:</b><br>\n      <b>(a) Current Density (j):</b><br>\n      j = I / A = (1.5 A) / (1.0 &times; 10<sup>-7</sup> m<sup>2</sup>) = <b>1.5 &times; 10<sup>7</sup> A m<sup>-2</sup></b>.<br><br>\n      <b>(b) Drift Velocity (v<sub>d</sub>):</b><br>\n      Using I = n e A v<sub>d</sub> &rarr; v<sub>d</sub> = I / (n e A) = j / (n e):<br>\n      v<sub>d</sub> = (1.5 &times; 10<sup>7</sup>) / [(8.5 &times; 10<sup>28</sup>) &times; (1.6 &times; 10<sup>-19</sup>)]<br>\n      v<sub>d</sub> = (1.5 &times; 10<sup>7</sup>) / (1.36 &times; 10<sup>10</sup>) = <b>1.10 &times; 10<sup>-3</sup> m s<sup>-1</sup> = 1.10 mm s<sup>-1</sup></b>.\n    </div>\n  </div>\n\n  <!-- SVG 1 -->\n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 1. FLOW OF CHARGES &amp; DRIFT VELOCITY IN A METALLIC CONDUCTOR\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"eGlow\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"100%\" stop-color=\"#0072FF\"/>\n    </radialGradient>\n    <radialGradient id=\"ionGlow\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <marker id=\"mPurple\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#8E2DE2\"/>\n    </marker>\n    <marker id=\"mCyan\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"mGreen\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"mGold\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#FFD700\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#8E2DE2\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">1. FLOW OF CHARGES &amp; DRIFT VELOCITY IN METALLIC CONDUCTOR</text>\n\n    <!-- Conductor Cylinder -->\n    <rect x=\"180\" y=\"110\" width=\"600\" height=\"240\" rx=\"0\" fill=\"rgba(142,45,226,0.08)\" stroke=\"#8E2DE2\" stroke-width=\"2.5\"/>\n    <ellipse cx=\"180\" cy=\"230\" rx=\"35\" ry=\"120\" fill=\"#1E1B4B\" stroke=\"#8E2DE2\" stroke-width=\"2.5\"/>\n    <ellipse cx=\"780\" cy=\"230\" rx=\"35\" ry=\"120\" fill=\"#2E1065\" stroke=\"#8E2DE2\" stroke-width=\"2.5\"/>\n\n    <!-- Electric Field E Vector -->\n    <line x1=\"250\" y1=\"80\" x2=\"710\" y2=\"80\" stroke=\"#FFD700\" stroke-width=\"3.5\" marker-end=\"url(#mGold)\"/>\n    <text x=\"480\" y=\"70\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Electric Field E (Left to Right)</text>\n\n    <!-- Conventional Current I Vector -->\n    <line x1=\"250\" y1=\"380\" x2=\"710\" y2=\"380\" stroke=\"#76FF03\" stroke-width=\"3.5\" marker-end=\"url(#mGreen)\"/>\n    <text x=\"480\" y=\"405\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Conventional Current I = n e A v_d (Left to Right)</text>\n\n    <!-- Positive Lattice Ions -->\n    <circle cx=\"280\" cy=\"180\" r=\"16\" fill=\"url(#ionGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"280\" y=\"186\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">+Cu</text>\n\n    <circle cx=\"480\" cy=\"160\" r=\"16\" fill=\"url(#ionGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"480\" y=\"166\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">+Cu</text>\n\n    <circle cx=\"680\" cy=\"200\" r=\"16\" fill=\"url(#ionGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"680\" y=\"206\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">+Cu</text>\n\n    <circle cx=\"380\" cy=\"290\" r=\"16\" fill=\"url(#ionGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"380\" y=\"296\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">+Cu</text>\n\n    <circle cx=\"580\" cy=\"280\" r=\"16\" fill=\"url(#ionGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"580\" y=\"286\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">+Cu</text>\n\n    <!-- Electrons Drifting to Left -->\n    <circle cx=\"700\" cy=\"150\" r=\"14\" fill=\"url(#eGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"700\" y=\"155\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">e-</text>\n    <line x1=\"680\" y1=\"150\" x2=\"590\" y2=\"150\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan)\"/>\n    <text x=\"635\" y=\"140\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">v_d</text>\n\n    <path d=\"M 540 230 L 490 200 L 450 250 L 370 210\" fill=\"none\" stroke=\"#94A3B8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n    <circle cx=\"370\" cy=\"210\" r=\"14\" fill=\"url(#eGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"370\" y=\"215\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">e-</text>\n    <line x1=\"350\" y1=\"210\" x2=\"260\" y2=\"210\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan)\"/>\n    <text x=\"305\" y=\"200\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">v_d</text>\n\n    <circle cx=\"530\" cy=\"310\" r=\"14\" fill=\"url(#eGlow)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n    <text x=\"530\" y=\"315\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">e-</text>\n    <line x1=\"510\" y1=\"310\" x2=\"420\" y2=\"310\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan)\"/>\n    <text x=\"465\" y=\"300\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">v_d</text>\n\n    <!-- Dimensions -->\n    <line x1=\"180\" y1=\"365\" x2=\"780\" y2=\"365\" stroke=\"#E2E8F0\" stroke-width=\"1.5\"/>\n    <text x=\"480\" y=\"358\" text-anchor=\"middle\" fill=\"#E2E8F0\" font-family=\"sans-serif\" font-size=\"15\">Length L</text>\n    <text x=\"120\" y=\"235\" text-anchor=\"middle\" fill=\"#E2E8F0\" font-family=\"sans-serif\" font-size=\"15\">Area A</text>\n\n    <rect x=\"25\" y=\"445\" width=\"880\" height=\"48\" rx=\"8\" fill=\"rgba(142,45,226,0.15)\" stroke=\"#8E2DE2\" stroke-width=\"1.2\"/>\n    <text x=\"465\" y=\"475\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">v_d = (e E &#964;) / m  |  I = n e A v_d  |  j = &#963; E  |  Mobility &#956; = v_d / E</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 1.1: Microscopic view of electron drift velocity (v<sub>d</sub>) opposite to electric field E, collision with lattice ions (+Cu), and resulting conventional current I = n e A v<sub>d</sub>.\n    </div>\n  </div>\n\n  <!-- SECTION 2 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">2. Ohm's Law, Electrical Resistivity, Conductivity &amp; Temperature Dependence of Resistance</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(142, 45, 226, 0.4); border-left: 5px solid #8E2DE2; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #8E2DE2; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Electrical Resistivity (&rho;)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Intrinsic resistance offered by unit length of conductor with unit cross-sectional area: <b>&rho; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &tau;</span></span></b> &nbsp;|&nbsp; Conductivity: <b>&sigma; = 1 / &rho; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &tau;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">Ohm-meter (&Omega; m)</span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>1</sup> L<sup>3</sup> T<sup>-3</sup> A<sup>-2</sup>]</span></span>\n    </div>\n  </div>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #38BDF8; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #38BDF8; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: Resistance vs Resistivity</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Resistivity (&rho;) is an intrinsic material property like the stickiness of honey or mud. Resistance (R) is the total difficulty of moving through a specific pipe: R = &rho; L / A (longer pipe = more resistance; wider pipe = less resistance).</div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.35); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #8E2DE2; font-size: 15.5px; font-weight: bold; margin-bottom: 6px;\">📝 WORKED BOARD NUMERICAL #1</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; margin-bottom: 8px;\"><b>Problem:</b> A copper wire has 8.5 &times; 10<sup>28</sup> free electrons/m<sup>3</sup>, length 3.0 m, and cross-section 2.0 &times; 10<sup>-6</sup> m<sup>2</sup> carrying 3.0 A. Find the drift velocity of electrons.</div>\n    <div style=\"background: rgba(0,0,0,0.3); padding: 10px 14px; border-radius: 6px; color: #69F0AE; font-size: 14px; line-height: 1.6;\">\n      <b style=\"color: #8E2DE2;\">Solution:</b><br>Formula: v<sub>d</sub> = I / (n e A)<br>v<sub>d</sub> = 3.0 / [(8.5 &times; 10<sup>28</sup>) &times; (1.6 &times; 10<sup>-19</sup>) &times; (2.0 &times; 10<sup>-6</sup>)] = 3.0 / [2.72 &times; 10<sup>4</sup>] = <b>1.10 &times; 10<sup>-4</sup> m/s (0.11 mm/s)</b>.\n    </div>\n  </div>\n\n  <p>In 1827, German physicist Georg Simon Ohm experimentally discovered the fundamental linear relationship governing the flow of electric current through metallic conductors.</p>\n\n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Ohm's Law &amp; Electrical Resistance (R)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\"><b>Ohm's Law:</b> Under constant physical conditions (such as temperature, mechanical strain, and pressure), the electric current (I) flowing through a conductor is directly proportional to the potential difference (V) applied across its terminals: V &prop; I &rArr; <b>V = I R</b>.<br><br><b>Electrical Resistance (R):</b> The opposition offered by a conductor to the flow of electric current through it: R = V / I. SI Unit: Ohm (&Omega;) = 1 Volt / 1 Ampere (V A<sup>-1</sup>). Dimensional Formula: [M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-2</sup>].</div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(i) Microscopic Deduction of Ohm's Law from Drift Theory</h3>\n\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(142, 45, 226, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(142, 45, 226, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Deduction of Ohm's Law (R = &#961; L / A)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      <b>1. Drift Velocity Expression:</b><br>\n      v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span> &nbsp; (since electric field E = V / L).<br><br>\n      <b>2. Substitute v<sub>d</sub> into Current Equation:</b><br>\n      I = n e A v<sub>d</sub> = n e A [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964; A</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span>] V.<br><br>\n      <b>3. Rearranging for Potential Difference V:</b><br>\n      V = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span>] I = <b>R I</b>.<br><br>\n      At constant temperature, m, n, e, &#964;, L, and A are strictly constant, so V / I = Constant = R.<br><br>\n      <b>4. Electrical Resistivity (&#961;):</b><br>\n      R = &#961; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span> &nbsp;&rArr;&nbsp; <b>&#961; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span></b>.<br><br>\n      <b>5. Electrical Conductivity (&#963;):</b><br>\n      <b>&#963; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&#961;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>. Vector form of Ohm's Law: <b>j = &#963; E</b>.\n    </div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(ii) Temperature Dependence of Electrical Resistance &amp; Resistivity</h3>\n  <p>The electrical resistivity &#961; = m / (n e<sup>2</sup> &#964;) depends on free electron density n and relaxation time &#964;. When temperature T rises:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Metals / Metallic Conductors:</b> Electron density n is constant. Increased thermal vibrations of lattice ions increase the frequency of collisions, causing relaxation time &#964; to decrease. Hence, resistivity <b>&#961; increases with temperature</b>.\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid #8E2DE2; border-radius: 6px; padding: 8px; margin: 8px 0; text-align: center;\">\n      <b>R<sub>T</sub> = R<sub>0</sub> [1 + &alpha; (T - T<sub>0</sub>)] &nbsp;|&nbsp; &#961;<sub>T</sub> = &#961;<sub>0</sub> [1 + &alpha; (T - T<sub>0</sub>)]</b>\n    </div>\n    Here &alpha; is the positive temperature coefficient of resistance (for Cu, &alpha; &approx; +0.0039 K<sup>-1</sup>).</li>\n    <li><b>Semiconductors &amp; Insulators:</b> Thermal energy breaks covalent bonds, causing free carrier density n to increase exponentially [n &prop; e<sup>-E<sub>g</sub>/(2 k<sub>B</sub> T)</sup>]. The massive increase in n dominates over the slight decrease in &#964;, causing resistivity to <b>decrease exponentially with temperature</b> (&alpha; is negative).</li>\n    <li><b>Standard Resistance Alloys (Manganin, Constantan, Nichrome):</b> High resistivity with nearly zero temperature coefficient (&alpha; &approx; 10<sup>-5</sup> K<sup>-1</sup>). Therefore, they are universally used to construct standard resistance boxes and potentiometer wires.</li>\n  </ul>\n\n  <!-- SECTION 3 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">3. V-I Characteristics: Linear (Ohmic) &amp; Non-Linear (Non-Ohmic) Devices</h2>\n\n  <p>Electrical devices and materials are broadly categorized based on their current-voltage (V-I) response curves:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Ohmic Conductors:</b> Conductors that obey Ohm's law strictly across all voltages. Their V-I graph is a perfectly straight line passing through the origin (e.g. Copper, Silver wire at constant temperature). Resistance R = V / I = 1 / (slope of I-V graph).</li>\n    <li><b>Non-Ohmic Conductors / Devices:</b> Devices that violate Ohm's law. Their V-I graph is non-linear, does not pass through origin, or is asymmetrical under polarity reversal. Key examples:\n      <ol style=\"margin-left: 20px;\">\n        <li><i>P-N Junction Diode:</i> High non-linear current in forward bias (exponential), negligible current in reverse bias until breakdown.</li>\n        <li><i>Thyristor:</i> Exhibits multiple conduction states and switching regions.</li>\n        <li><i>Gallium Arsenide (GaAs):</i> Displays a <b>Negative Differential Resistance</b> region where current decreases as voltage increases (dI/dV &lt; 0).</li>\n        <li><i>Electrolytes &amp; Vacuum Tubes:</i> Non-linear due to space charge and ionic back EMF.</li>\n      </ol>\n    </li>\n  </ul>\n\n  <!-- SVG 2 -->\n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 2. V-I CHARACTERISTICS: OHMIC VS NON-OHMIC MATERIALS\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <marker id=\"mAxis\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#94A3B8\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#8E2DE2\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">2. V-I CHARACTERISTICS: OHMIC VS NON-OHMIC CONDUCTORS</text>\n\n    <!-- Panel 1: Ohmic Conductor -->\n    <g transform=\"translate(25, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"275\" height=\"370\" rx=\"10\" fill=\"rgba(142,45,226,0.06)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n      <text x=\"137\" y=\"32\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Metallic Conductor (Ohmic)</text>\n      <line x1=\"45\" y1=\"310\" x2=\"250\" y2=\"310\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mAxis)\"/>\n      <line x1=\"45\" y1=\"310\" x2=\"45\" y2=\"70\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mAxis)\"/>\n      <text x=\"245\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">I (Current)</text>\n      <text x=\"20\" y=\"65\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">V</text>\n      <line x1=\"45\" y1=\"310\" x2=\"225\" y2=\"100\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n      <text x=\"150\" y=\"180\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Slope = R = V/I</text>\n      <text x=\"137\" y=\"355\" text-anchor=\"middle\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13\">Strictly Linear (Ohm's Law holds)</text>\n    </g>\n\n    <!-- Panel 2: P-N Junction Diode -->\n    <g transform=\"translate(325, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"275\" height=\"370\" rx=\"10\" fill=\"rgba(0,229,255,0.06)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n      <text x=\"137\" y=\"32\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">P-N Junction Diode (Non-Ohmic)</text>\n      <line x1=\"30\" y1=\"260\" x2=\"255\" y2=\"260\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mAxis)\"/>\n      <line x1=\"90\" y1=\"340\" x2=\"90\" y2=\"60\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mAxis)\"/>\n      <text x=\"250\" y=\"285\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">V_F</text>\n      <text x=\"70\" y=\"55\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">I_F</text>\n      <path d=\"M 90 260 Q 140 260 170 220 T 220 80\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n      <path d=\"M 90 260 L 50 262 L 40 320\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n      <text x=\"140\" y=\"240\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">V_knee</text>\n      <text x=\"137\" y=\"355\" text-anchor=\"middle\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13\">Exponential (Non-linear)</text>\n    </g>\n\n    <!-- Panel 3: GaAs -->\n    <g transform=\"translate(625, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"275\" height=\"370\" rx=\"10\" fill=\"rgba(255,81,47,0.06)\" stroke=\"#FF8A65\" stroke-width=\"1.5\"/>\n      <text x=\"137\" y=\"32\" text-anchor=\"middle\" fill=\"#FF8A65\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">GaAs (Negative Resistance)</text>\n      <line x1=\"45\" y1=\"310\" x2=\"250\" y2=\"310\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mAxis)\"/>\n      <line x1=\"45\" y1=\"310\" x2=\"45\" y2=\"70\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mAxis)\"/>\n      <text x=\"245\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">V</text>\n      <text x=\"25\" y=\"65\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">I</text>\n      <path d=\"M 45 310 Q 90 140 130 130 T 180 220 T 235 150\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3.5\"/>\n      <text x=\"120\" y=\"115\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Ohmic</text>\n      <text x=\"140\" y=\"185\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">-&#916;V/&#916;I &lt; 0</text>\n      <text x=\"137\" y=\"355\" text-anchor=\"middle\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13\">Negative Dynamic Resistance Region</text>\n    </g>\n\n    <rect x=\"25\" y=\"445\" width=\"880\" height=\"48\" rx=\"8\" fill=\"rgba(142,45,226,0.15)\" stroke=\"#8E2DE2\" stroke-width=\"1.2\"/>\n    <text x=\"465\" y=\"475\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Dynamic Resistance: r_d = &#916;V / &#916;I  |  Non-Ohmic: Diodes, Transistors, Electrolytes, Arc Lamps</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 2.1: Comparison of linear Ohmic V-I graph with non-linear p-n junction diode and negative differential resistance in GaAs.\n    </div>\n  </div>\n\n  <!-- SECTION 4 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">4. Electrical Energy, Electrical Power &amp; Joule's Heating Effect</h2>\n\n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electrical Energy &amp; Electrical Power (P)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\"><b>Electrical Energy (W):</b> The total work done by a source of EMF in maintaining a steady current I through an electric circuit of resistance R for time t: W = V I t = I<sup>2</sup> R t = (V<sup>2</sup> / R) t [Joules J].<br><br><b>Electrical Power (P):</b> The rate at which electrical energy is consumed or dissipated into heat: P = dW / dt = <b>V I = I<sup>2</sup> R = V<sup>2</sup> / R</b>. SI Unit: Watt (W) = 1 Joule per second (J s<sup>-1</sup>). Commercial unit: <b>1 Kilowatt-hour (1 kWh) = 1 Board of Trade Unit = 3.6 &times; 10<sup>6</sup> J</b>.</div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(i) Power Dissipation in Series vs Parallel Bulb Combinations</h3>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Resistance from Rated Values:</b> For an electric bulb rated as (P<sub>rated</sub>, V<sub>rated</sub>), its filament resistance is <b>R = V<sub>rated</sub><sup>2</sup> / P<sub>rated</sub></b> (Higher rated power &rArr; Lower resistance).</li>\n    <li><b>Bulbs Connected in Series:</b> Current I is identical through all bulbs. Power dissipated P = I<sup>2</sup> R &prop; R. Therefore, the bulb with <b>higher resistance (lower rated power) glows brighter</b>.</li>\n    <li><b>Bulbs Connected in Parallel:</b> Voltage V is identical across all bulbs. Power dissipated P = V<sup>2</sup> / R &prop; 1/R. Therefore, the bulb with <b>lower resistance (higher rated power) glows brighter</b>.</li>\n  </ul>\n\n  <!-- SECTION 5 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">5. Internal Resistance of a Cell, Potential Difference &amp; Electromotive Force (EMF)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(142, 45, 226, 0.4); border-left: 5px solid #8E2DE2; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #8E2DE2; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Electromotive Force (EMF) &amp; Internal Resistance (&Epsilon;, r)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Maximum potential difference between the terminals of a cell in an open circuit (when no current is drawn): <b>&Epsilon; = W / q</b>. Internal resistance: <b>r = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&Epsilon;</span><span style=\"padding: 0 2px; display: inline-block;\">V</span></span> - 1) R</b>.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">Volt (V), Ohm (&Omega;)</span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>]</span></span>\n    </div>\n  </div>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #38BDF8; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #38BDF8; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: EMF vs Terminal Voltage Analogy</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">EMF (&Epsilon;) is the gross salary promised by an employer ($100). The cell's internal resistance is like an unavoidable commuting tax (Ir = $10). Terminal voltage (V = &Epsilon; - Ir = $90) is the net take-home cash available to spend on external circuit appliances (R)!</div>\n  </div>\n  <div style=\"background: rgba(220, 38, 38, 0.1); border: 1.2px solid rgba(239, 68, 68, 0.4); border-left: 5px solid #EF4444; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #F87171; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">⚠️ BOARD EXAM TRAP &amp; CONCEPTUAL PITFALL: Terminal Voltage Exceeding EMF During Cell Charging</div>\n    <div style=\"color: #FCA5A5; font-size: 14.5px; line-height: 1.6;\">During normal discharging: <b>V = &Epsilon; - I r</b> (V &lt; &Epsilon;). But when a secondary cell is being CHARGED by an external charger, current flows into the positive terminal: <b>V = &Epsilon; + I r</b> (Terminal voltage V is strictly GREATER than EMF &Epsilon;!).</div>\n  </div>\n\n  <p>An electrochemical cell converts chemical energy into electrical energy through redox reactions occurring at its electrodes. Within the cell, non-electrostatic chemical forces perform work to pump positive charge from the lower potential cathode to the higher potential anode against electrostatic repulsive fields.</p>\n\n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: EMF (&#949;), Terminal Potential Difference (V) &amp; Internal Resistance (r)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\"><b>Electromotive Force (EMF, &#949;):</b> The maximum potential difference between the electrodes of a cell when no current is drawn from it (open circuit): &#949; = dW / dq [Volt V, Dimensions: [M L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>]].<br><br><b>Terminal Potential Difference (V):</b> The potential difference between the terminals of a cell when current I is drawn in a closed circuit.<br><br><b>Internal Resistance (r):</b> The opposition offered by the chemical electrolyte and electrodes of the cell to the flow of internal ionic current. Formula: <b>r = R [(&#949; / V) - 1]</b>.</div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(i) Mathematical Relationship During Different Operational Modes</h3>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Discharging Mode (Cell supplying current to load R):</b><br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\">I = &#949; / (R + r) &nbsp;&rArr;&nbsp; <b>V = &#949; - I r</b> &nbsp; (Terminal voltage V &lt; &#949;)</span></li>\n    <li><b>Charging Mode (External charger forcing current into cell from + to -):</b><br>\n    <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>V = &#949; + I r</b> &nbsp; (Terminal voltage V &gt; &#949;)</span></li>\n    <li><b>Open Circuit Condition (I = 0):</b><br>\n    <span style=\"color: #FFD700; font-family: monospace; font-size: 16px;\"><b>V = &#949;</b> &nbsp; (Terminal voltage equals true EMF)</span></li>\n    <li><b>Short Circuit Condition (R = 0):</b><br>\n    <span style=\"color: #FF512F; font-family: monospace; font-size: 16px;\"><b>I<sub>max</sub> = &#949; / r</b> &nbsp; (Terminal voltage V = 0, maximum dangerous current)</span></li>\n  </ul>\n\n  <!-- SVG 3 -->\n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 3. EMF, INTERNAL RESISTANCE &amp; TERMINAL VOLTAGE IN A CELL\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <marker id=\"mGreen3\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"mPurple3\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#8E2DE2\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#8E2DE2\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">3. EMF (&#949;), INTERNAL RESISTANCE (r) &amp; TERMINAL POTENTIAL DIFFERENCE (V)</text>\n\n    <!-- Circuit Diagram Box -->\n    <g transform=\"translate(35, 65)\">\n      <rect x=\"0\" y=\"0\" width=\"460\" height=\"360\" rx=\"10\" fill=\"rgba(142,45,226,0.06)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n      <text x=\"230\" y=\"30\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Cell in Closed Circuit (Discharging)</text>\n\n      <rect x=\"70\" y=\"60\" width=\"320\" height=\"110\" rx=\"8\" fill=\"rgba(255,215,0,0.06)\" stroke=\"#FFD700\" stroke-width=\"1.5\" stroke-dasharray=\"6,4\"/>\n      <text x=\"230\" y=\"85\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Real Cell (EMF &#949; + Internal Resistance r)</text>\n\n      <line x1=\"120\" y1=\"125\" x2=\"120\" y2=\"155\" stroke=\"#76FF03\" stroke-width=\"4\"/>\n      <line x1=\"140\" y1=\"110\" x2=\"140\" y2=\"170\" stroke=\"#76FF03\" stroke-width=\"5\"/>\n      <text x=\"110\" y=\"105\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">-</text>\n      <text x=\"145\" y=\"105\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">+</text>\n      <text x=\"130\" y=\"195\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">&#949;</text>\n\n      <line x1=\"140\" y1=\"140\" x2=\"220\" y2=\"140\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n      <path d=\"M 220 140 L 230 125 L 245 155 L 260 125 L 275 155 L 290 125 L 300 140\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n      <text x=\"260\" y=\"180\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">r (Internal)</text>\n      <line x1=\"300\" y1=\"140\" x2=\"360\" y2=\"140\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n      <line x1=\"70\" y1=\"140\" x2=\"40\" y2=\"140\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n      <line x1=\"40\" y1=\"140\" x2=\"40\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n      <line x1=\"40\" y1=\"280\" x2=\"160\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n      <path d=\"M 160 280 L 175 265 L 195 295 L 215 265 L 235 295 L 255 265 L 270 280\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n      <text x=\"215\" y=\"325\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Load Resistor R</text>\n      <line x1=\"270\" y1=\"280\" x2=\"420\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n      <line x1=\"420\" y1=\"280\" x2=\"420\" y2=\"140\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n      <line x1=\"420\" y1=\"140\" x2=\"390\" y2=\"140\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n      <line x1=\"40\" y1=\"210\" x2=\"40\" y2=\"250\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen3)\"/>\n      <text x=\"25\" y=\"235\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">I</text>\n    </g>\n\n    <!-- Graph Panel -->\n    <g transform=\"translate(520, 65)\">\n      <rect x=\"0\" y=\"0\" width=\"375\" height=\"360\" rx=\"10\" fill=\"rgba(0,229,255,0.06)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n      <text x=\"187\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">V vs I Characteristics of Cell</text>\n\n      <line x1=\"50\" y1=\"260\" x2=\"330\" y2=\"260\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mGreen3)\"/>\n      <line x1=\"50\" y1=\"260\" x2=\"50\" y2=\"60\" stroke=\"#94A3B8\" stroke-width=\"2\" marker-end=\"url(#mPurple3)\"/>\n      <text x=\"335\" y=\"285\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Current I</text>\n      <text x=\"30\" y=\"55\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Terminal V</text>\n\n      <line x1=\"50\" y1=\"100\" x2=\"280\" y2=\"260\" stroke=\"#FF512F\" stroke-width=\"3.5\"/>\n      <circle cx=\"50\" cy=\"100\" r=\"5\" fill=\"#FFD700\"/>\n      <text x=\"65\" y=\"95\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V = &#949; (at I = 0)</text>\n\n      <circle cx=\"280\" cy=\"260\" r=\"5\" fill=\"#FF512F\"/>\n      <text x=\"240\" y=\"290\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">I_sc = &#949;/r</text>\n\n      <text x=\"180\" y=\"160\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Slope = -r</text>\n      <text x=\"180\" y=\"185\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\">V = &#949; - I r</text>\n\n      <rect x=\"25\" y=\"305\" width=\"325\" height=\"40\" rx=\"6\" fill=\"rgba(0,0,0,0.3)\" stroke=\"#00E5FF\" stroke-width=\"1\"/>\n      <text x=\"187\" y=\"330\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">r = R (&#949;/V - 1)  |  P_max when R = r</text>\n    </g>\n\n    <rect x=\"25\" y=\"445\" width=\"880\" height=\"48\" rx=\"8\" fill=\"rgba(142,45,226,0.15)\" stroke=\"#8E2DE2\" stroke-width=\"1.2\"/>\n    <text x=\"465\" y=\"475\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Discharging: V = &#949; - I r  |  Charging: V = &#949; + I r  |  Open Circuit: V = &#949;  |  Short Circuit: I_max = &#949; / r</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 3.1: Circuit diagram of cell with internal resistance r connected to load R and V vs I discharging characteristic line with intercept &#949; and slope -r.\n    </div>\n  </div>\n\n  <!-- SECTION 6 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">6. Kirchhoff's Rules &amp; Wheatstone Bridge Principle</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(142, 45, 226, 0.4); border-left: 5px solid #8E2DE2; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #8E2DE2; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Kirchhoff's Rules (&Sigma; I = 0, &Sigma; &Delta;V = 0)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">1. <b>Junction Rule (KCL):</b> &Sigma; I = 0 (Conservation of Charge).<br>2. <b>Loop Rule (KVL):</b> &Sigma; &Delta;V = &Sigma; &Epsilon; - &Sigma; I R = 0 (Conservation of Energy).</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">Ampere (A), Volt (V)</span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[A<sup>1</sup>], [M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>]</span></span>\n    </div>\n  </div>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #38BDF8; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #38BDF8; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: Wheatstone Bridge Balance Analogy</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Think of a Wheatstone bridge as a balanced two-pan weighing scale. When the ratio of left arms equals the ratio of right arms (P / Q = R / S), both bridge nodes reach the EXACT SAME electric potential (V<sub>B</sub> = V<sub>D</sub>). Zero current flows through the central galvanometer branch (I<sub>g</sub> = 0)!</div>\n  </div>\n\n  <p>While simple series-parallel circuits can be reduced using Ohm's law, complex electrical networks containing multiple loops, branches, and interconnected electromotive sources require Kirchhoff's Laws, formulated by Gustav Kirchhoff in 1845.</p>\n\n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Kirchhoff's First Rule (Junction Rule / KCL)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Kirchhoff's Junction Rule states that the algebraic sum of electric currents entering and leaving any electrical node or junction in a circuit is strictly zero: <b>&Sigma; I = 0</b>. Sum of entering currents = Sum of leaving currents. This rule is a direct physical consequence of the <b>Law of Conservation of Electric Charge</b>.</div>\n  </div>\n\n  <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4.5px solid #8E2DE2; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Kirchhoff's Second Rule (Loop Rule / KVL)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Kirchhoff's Loop Rule states that the algebraic sum of changes in electrostatic potential around any closed mesh or loop of an electrical circuit is strictly zero: <b>&Sigma; &Delta;V = 0 &rArr; &Sigma; &#949; = &Sigma; I R</b>. This rule is a direct physical consequence of the <b>Law of Conservation of Energy</b> (electrostatic field is conservative).</div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(i) Wheatstone Bridge Network &amp; Balanced Condition Derivation</h3>\n\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(142, 45, 226, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(142, 45, 226, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Balanced Wheatstone Bridge Condition (P / Q = R / S)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      <b>1. Circuit Setup:</b><br>\n      Four resistors P, Q, R, S form four arms of a quadrilateral ABCD. Battery of EMF &#949; is connected across opposite junctions A and C; Galvanometer G (resistance G) is connected across junctions B and D.<br><br>\n      <b>2. Applying Kirchhoff's Junction Rule:</b><br>\n      At node B: I<sub>1</sub> = I<sub>g</sub> + I<sub>Q</sub> &nbsp;&rArr;&nbsp; I<sub>Q</sub> = I<sub>1</sub> - I<sub>g</sub>.<br>\n      At node D: I<sub>2</sub> + I<sub>g</sub> = I<sub>S</sub> &nbsp;&rArr;&nbsp; I<sub>S</sub> = I<sub>2</sub> + I<sub>g</sub>.<br><br>\n      <b>3. Applying Kirchhoff's Loop Rule to Mesh ABDA:</b><br>\n      - I<sub>1</sub> P - I<sub>g</sub> G + I<sub>2</sub> R = 0 &nbsp;&rArr;&nbsp; I<sub>1</sub> P + I<sub>g</sub> G = I<sub>2</sub> R &nbsp;--- (Equation 1).<br><br>\n      <b>4. Applying Kirchhoff's Loop Rule to Mesh BCDB:</b><br>\n      - (I<sub>1</sub> - I<sub>g</sub>) Q + (I<sub>2</sub> + I<sub>g</sub>) S + I<sub>g</sub> G = 0 &nbsp;--- (Equation 2).<br><br>\n      <b>5. Balanced Bridge Condition (Null Deflection I<sub>g</sub> = 0):</b><br>\n      When potential at B equals potential at D (V<sub>B</sub> = V<sub>D</sub>), zero current flows through galvanometer (I<sub>g</sub> = 0).<br>\n      From Equation (1): I<sub>1</sub> P = I<sub>2</sub> R.<br>\n      From Equation (2): I<sub>1</sub> Q = I<sub>2</sub> S.<br><br>\n      <b>6. Dividing the two equations:</b><br>\n      <div style=\"background: rgba(0,0,0,0.35); border: 1px solid #8E2DE2; border-radius: 6px; padding: 10px; text-align: center; color: #FFFFFF; font-size: 16.5px;\">\n        <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">I<sub>1</sub> P</span><span style=\"padding: 0 2px; display: inline-block;\">I<sub>1</sub> Q</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">I<sub>2</sub> R</span><span style=\"padding: 0 2px; display: inline-block;\">I<sub>2</sub> S</span></span> &nbsp;&rArr;&nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P</span><span style=\"padding: 0 2px; display: inline-block;\">Q</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">S</span></span></b>\n      </div><br>\n      <b>Conclusion:</b> Under balanced condition, ratio P/Q equals R/S. The galvanometer can be interchanged with the battery without disturbing the null condition.\n    </div>\n  </div>\n\n  <!-- SVG 4 -->\n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 4. WHEATSTONE BRIDGE &amp; KIRCHHOFF'S CURRENT/VOLTAGE LOOPS\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"gGlow\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"100%\" stop-color=\"#D97706\"/>\n    </radialGradient>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#8E2DE2\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">4. WHEATSTONE BRIDGE &amp; KIRCHHOFF'S LAWS</text>\n\n    <!-- Arm AB (Resistor P) -->\n    <line x1=\"180\" y1=\"240\" x2=\"310\" y2=\"175\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <path d=\"M 310 175 L 320 160 L 340 190 L 360 160 L 380 190 L 400 160 L 410 175\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n    <line x1=\"410\" y1=\"175\" x2=\"465\" y2=\"100\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <text x=\"340\" y=\"145\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Arm P (I1)</text>\n\n    <!-- Arm BC (Resistor Q) -->\n    <line x1=\"465\" y1=\"100\" x2=\"520\" y2=\"175\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <path d=\"M 520 175 L 530 160 L 550 190 L 570 160 L 590 190 L 610 160 L 620 175\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n    <line x1=\"620\" y1=\"175\" x2=\"750\" y2=\"240\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <text x=\"590\" y=\"145\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Arm Q (I1 - Ig)</text>\n\n    <!-- Arm AD (Resistor R) -->\n    <line x1=\"180\" y1=\"240\" x2=\"310\" y2=\"305\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <path d=\"M 310 305 L 320 290 L 340 320 L 360 290 L 380 320 L 400 290 L 410 305\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n    <line x1=\"410\" y1=\"305\" x2=\"465\" y2=\"380\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <text x=\"340\" y=\"340\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Arm R (I2)</text>\n\n    <!-- Arm DC (Resistor S) -->\n    <line x1=\"465\" y1=\"380\" x2=\"520\" y2=\"305\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <path d=\"M 520 305 L 530 290 L 550 320 L 570 290 L 590 320 L 610 290 L 620 305\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n    <line x1=\"620\" y1=\"305\" x2=\"750\" y2=\"240\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <text x=\"590\" y=\"340\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Arm S (I2 + Ig)</text>\n\n    <!-- Galvanometer Arm BD -->\n    <line x1=\"465\" y1=\"100\" x2=\"465\" y2=\"205\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n    <circle cx=\"465\" cy=\"240\" r=\"32\" fill=\"url(#gGlow)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"247\" text-anchor=\"middle\" fill=\"#0B0F19\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">G</text>\n    <line x1=\"465\" y1=\"275\" x2=\"465\" y2=\"380\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n    <text x=\"510\" y=\"245\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Ig = 0</text>\n\n    <!-- Node Labels -->\n    <circle cx=\"180\" cy=\"240\" r=\"8\" fill=\"#8E2DE2\"/>\n    <text x=\"150\" y=\"245\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">A</text>\n\n    <circle cx=\"465\" cy=\"100\" r=\"8\" fill=\"#8E2DE2\"/>\n    <text x=\"465\" y=\"78\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">B (V_B)</text>\n\n    <circle cx=\"750\" cy=\"240\" r=\"8\" fill=\"#8E2DE2\"/>\n    <text x=\"770\" y=\"245\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">C</text>\n\n    <circle cx=\"465\" cy=\"380\" r=\"8\" fill=\"#8E2DE2\"/>\n    <text x=\"465\" y=\"410\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">D (V_D)</text>\n\n    <!-- Battery Connections -->\n    <path d=\"M 180 240 L 90 240 L 90 460 L 400 460\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <line x1=\"400\" y1=\"445\" x2=\"400\" y2=\"475\" stroke=\"#76FF03\" stroke-width=\"4\"/>\n    <line x1=\"415\" y1=\"435\" x2=\"415\" y2=\"485\" stroke=\"#76FF03\" stroke-width=\"5\"/>\n    <text x=\"408\" y=\"425\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">&#949;, K</text>\n    <path d=\"M 415 460 L 840 460 L 840 240 L 750 240\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n    <rect x=\"180\" y=\"440\" width=\"570\" height=\"48\" rx=\"8\" fill=\"rgba(142,45,226,0.2)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n    <text x=\"465\" y=\"470\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Balanced Condition: V_B = V_D &#8658; I_g = 0 &#8658; P / Q = R / S</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 4.1: Bridge network showing 4 arms P, Q, R, S, central galvanometer G, branch currents, and balanced null condition P/Q = R/S.\n    </div>\n  </div>\n\n  <!-- COMPARISON MATRICES -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">7. Master Comparison Matrices</h2>\n\n  <div style=\"overflow-x: auto; margin: 20px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; color: #FFFFFF; font-size: 15px; background: rgba(15,23,42,0.85); border: 1px solid #8E2DE2; border-radius: 8px;\">\n      <thead>\n        <tr style=\"background: rgba(142,45,226,0.3); color: #8E2DE2; border-bottom: 2px solid #8E2DE2;\">\n          <th style=\"padding: 12px; border: 1px solid rgba(142,45,226,0.3); text-align: left;\">Parameter</th>\n          <th style=\"padding: 12px; border: 1px solid rgba(142,45,226,0.3); text-align: left;\">Electromotive Force (EMF, &#949;)</th>\n          <th style=\"padding: 12px; border: 1px solid rgba(142,45,226,0.3); text-align: left;\">Terminal Potential Difference (V)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2); font-weight: bold; color: #8E2DE2;\">1. Definition</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Max work done by cell in driving unit charge through entire complete circuit.</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Work done in moving unit charge between two specific circuit points.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2); font-weight: bold; color: #8E2DE2;\">2. Circuit State</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Measured when circuit is <b>open</b> (no current I = 0).</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Measured when circuit is <b>closed</b> (current I &gt; 0).</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2); font-weight: bold; color: #8E2DE2;\">3. Dependence on R</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Independent of external load resistance R.</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Directly depends on external load resistance R.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2); font-weight: bold; color: #8E2DE2;\">4. Cause vs Effect</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">EMF is the <b>cause</b> of current flow.</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Potential difference is the <b>effect</b> of current flow.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2); font-weight: bold; color: #8E2DE2;\">5. Magnitude</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">Always greater than V during discharge (&#949; &gt; V).</td>\n          <td style=\"padding: 10px; border: 1px solid rgba(142,45,226,0.2);\">V = &#949; - I r (less than &#949; during discharge).</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- MASTER REVISION CHEAT SHEET -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">8. Master Revision Formula Cheat Sheet</h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; margin-top: 15px;\">\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid #8E2DE2; border-radius: 8px; padding: 12px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Drift Velocity &amp; Current</b>\n      <div style=\"color: #FFFFFF; font-size: 14.5px;\">\n        v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span><br>\n        I = n e A v<sub>d</sub><br>\n        j = I / A = n e v<sub>d</sub> = &#963; E<br>\n        &#956; = v<sub>d</sub> / E = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span>\n      </div>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid #8E2DE2; border-radius: 8px; padding: 12px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Resistance &amp; Temperature</b>\n      <div style=\"color: #FFFFFF; font-size: 14.5px;\">\n        R = &#961; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span> = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span>] <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span><br>\n        &#961; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span>, &nbsp; &#963; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&#961;</span></span><br>\n        R<sub>T</sub> = R<sub>0</sub> [1 + &alpha; (T - T<sub>0</sub>)]<br>\n        &alpha; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R<sub>2</sub> - R<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub>(T<sub>2</sub> - T<sub>1</sub>)</span></span>\n      </div>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid #8E2DE2; border-radius: 8px; padding: 12px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Energy &amp; Electrical Power</b>\n      <div style=\"color: #FFFFFF; font-size: 14.5px;\">\n        W = V I t = I<sup>2</sup> R t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span> t<br>\n        P = V I = I<sup>2</sup> R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span><br>\n        1 kWh = 3.6 &times; 10<sup>6</sup> J<br>\n        Bulb R = V<sub>rated</sub><sup>2</sup> / P<sub>rated</sub>\n      </div>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid #8E2DE2; border-radius: 8px; padding: 12px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Cells &amp; Kirchhoff's Laws</b>\n      <div style=\"color: #FFFFFF; font-size: 14.5px;\">\n        Discharging: V = &#949; - I r<br>\n        Charging: V = &#949; + I r<br>\n        Internal r = R [(&#949;/V) - 1]<br>\n        KCL: &Sigma; I = 0, &nbsp; KVL: &Sigma; &Delta;V = 0<br>\n        Wheatstone: P / Q = R / S (when I<sub>g</sub> = 0)\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c12Phy2HtmlSolutions = "<div style=\"padding: 12px; color: #FFFFFF; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n<h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 15px; margin-bottom: 20px;\">SECTION A: Very Short Answer Questions (1 Mark Each) — Q1 to Q40</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q1: Define electric current and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electric current is the net rate of flow of electric charge across any cross-section of a conductor: I = dq / dt. Its SI unit is the <b>Ampere (A)</b> [1 A = 1 Coulomb per second (C s<sup>-1</sup>)].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q2: Why is electric current considered a scalar quantity even though it is assigned a direction in circuits?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electric current is a scalar quantity because it obeys the ordinary algebraic laws of addition rather than the laws of vector addition (e.g. triangle or parallelogram law of vectors).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q3: Define one Ampere of electric current in terms of rate of charge flow.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">One Ampere is the steady electric current that flows through a conductor when a net charge of one Coulomb passes across any cross-section of the conductor in one second (1 A = 1 C s<sup>-1</sup>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q4: State the dimensional formula of electric current and electric charge.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Dimensional formula of Electric Current: <b>[M<sup>0</sup> L<sup>0</sup> T<sup>0</sup> A<sup>1</sup>]</b>.<br>Dimensional formula of Electric Charge: q = I t &rArr; <b>[M<sup>0</sup> L<sup>0</sup> T<sup>1</sup> A<sup>1</sup>]</b> = [A T].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q5: What is the typical order of magnitude of drift velocity of free electrons in a current-carrying metallic wire?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The typical order of magnitude of drift velocity of electrons under ordinary electric fields is <b>10<sup>-4</sup> m s<sup>-1</sup></b> (approx 0.1 to 1 mm s<sup>-1</sup>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q6: What is the approximate order of magnitude of random thermal speed of free electrons in a metal at room temperature (300 K)?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The random thermal speed of electrons at room temperature is of the order of <b>10<sup>5</sup> to 10<sup>6</sup> m s<sup>-1</sup></b> (approx 100 to 1000 km s<sup>-1</sup>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q7: Define relaxation time of free electrons in a metallic conductor.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Relaxation time (&#964;) is the average time interval elapsed between two successive collisions of a drifting free electron with the heavy positive metal lattice ions. Typical value: &#964; &approx; 10<sup>-14</sup> s.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q8: Write the mathematical expression for drift velocity in terms of electric field, charge, mass, and relaxation time.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>, where e is electron charge, E is electric field intensity, &#964; is relaxation time, and m is mass of electron (m &approx; 9.11 &times; 10<sup>-31</sup> kg).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q9: Define electron mobility and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electron mobility (&#956;) is defined as the magnitude of drift velocity acquired per unit applied electric field: &#956; = v<sub>d</sub> / E = (e &#964;) / m. Its SI unit is <b>m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q10: State the dimensional formula of electron mobility.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Mobility &#956; = [L T<sup>-1</sup>] / [M L T<sup>-3</sup> A<sup>-1</sup>] = <b>[M<sup>-1</sup> L<sup>0</sup> T<sup>2</sup> A<sup>1</sup>]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q11: How does the drift velocity of free electrons change if the potential difference across a conductor of length L is doubled?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Since v<sub>d</sub> = (e V &#964;) / (m L), drift velocity is directly proportional to potential difference V (v<sub>d</sub> &prop; V). Doubling V <b>doubles the drift velocity</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q12: A potential difference V is applied across a wire of length L. If the length is doubled keeping V constant, what happens to drift velocity?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Since v<sub>d</sub> = (e V &#964;) / (m L), v<sub>d</sub> &prop; 1/L for constant V. When length is doubled, drift velocity is <b>halved (v<sub>d</sub>' = v<sub>d</sub> / 2)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q13: State Ohm's law in scalar form.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Ohm's Law states that at constant temperature and physical conditions, the electric current (I) through a conductor is directly proportional to the potential difference (V) across its ends: <b>V = I R</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q14: State Ohm's law in vector microscopic form and define each term.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b><b>j</b> = &#963; <b>E</b> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&#961;</span></span> <b>E</b></b>, where <b>j</b> is current density vector, &#963; is electrical conductivity, &#961; is electrical resistivity, and <b>E</b> is electric field vector.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q15: Define electrical resistance of a conductor and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical resistance (R) is the physical property of a conductor by virtue of which it opposes the flow of electric current through it: R = V / I. Its SI unit is <b>Ohm (&Omega;) = 1 Volt per Ampere (V A<sup>-1</sup>)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q16: State the dimensional formula of electrical resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">R = V / I = [W / q] / I = [M L<sup>2</sup> T<sup>-2</sup>] / [A<sup>2</sup> T] = <b>[M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-2</sup>]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q17: Define electrical resistivity (specific resistance) of a material.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical resistivity (&#961;) is the electrical resistance offered by a unit cube of the material of a conductor across its opposite faces: &#961; = R A / L. It is an intrinsic property of the material.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q18: State the SI unit and dimensional formula of electrical resistivity.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">SI Unit: <b>Ohm-meter (&Omega; m)</b>.<br>Dimensional Formula: [&#961;] = [R] [A] / [L] = [M<sup>1</sup> L<sup>3</sup> T<sup>-3</sup> A<sup>-2</sup>].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q19: Define electrical conductivity and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical conductivity (&#963;) is the reciprocal of electrical resistivity: &#963; = 1 / &#961;. Its SI unit is <b>Siemens per meter (S m<sup>-1</sup>) or &Omega;<sup>-1</sup> m<sup>-1</sup> (mho m<sup>-1</sup>)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q20: How does the electrical resistivity of a typical metallic conductor (like copper) vary with temperature?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Resistivity of metals <b>increases with temperature</b> (&#961;<sub>T</sub> = &#961;<sub>0</sub>[1 + &alpha;(T - T<sub>0</sub>)]) because rising temperature increases lattice vibrations, reducing the electron relaxation time &#964;.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q21: Why does the resistivity of semiconductors (like Silicon or Germanium) decrease rapidly with increase in temperature?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">In semiconductors, rising temperature breaks covalent bonds, causing charge carrier density n to increase exponentially, which overcomes the decrease in &#964; and causes resistivity to drop exponentially.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q22: Name two alloys having very high resistivity and nearly zero temperature coefficient of resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Manganin</b> (Cu: 84%, Mn: 12%, Ni: 4%) and <b>Constantan / Eureka</b> (Cu: 55%, Ni: 45%).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q23: Why are standard resistance coils and potentiometer wires made of Manganin or Constantan rather than pure copper?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Because Manganin and Constantan possess high electrical resistivity and an almost negligible temperature coefficient of resistance (&alpha; &approx; 10<sup>-5</sup> K<sup>-1</sup>), maintaining constant resistance during heating.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q24: What is a superconductor and what is its resistance below critical temperature T<sub>c</sub>?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">A superconductor is a material whose electrical resistance drops strictly to <b>zero (R = 0, &#961; = 0)</b> when cooled below a characteristic critical transition temperature T<sub>c</sub> (e.g. Mercury at 4.2 K).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q25: Give three distinct examples of non-Ohmic conductors or devices.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. P-N Junction Diode, 2. Light Emitting Diode (LED) / Transistor, 3. Gallium Arsenide (GaAs) / Electrolyte.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q26: Define dynamic (differential) resistance of a non-linear electrical circuit element.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Dynamic resistance (r<sub>d</sub>) is defined as the ratio of a small change in potential difference (&Delta;V) to the corresponding small change in current (&Delta;I) in the non-linear operating region: <b>r<sub>d</sub> = &Delta;V / &Delta;I</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q27: Name one semiconductor material that displays negative dynamic resistance in its V-I characteristic curve.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Gallium Arsenide (GaAs)</b> (used in high-frequency microwave Gunn diodes).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q28: Define electrical power and write its three standard mathematical expressions in terms of V, I, and R.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical power (P) is the rate at which electrical energy is consumed or converted into other forms of energy: <b>P = V I = I<sup>2</sup> R = V<sup>2</sup> / R</b>. SI unit: <b>Watt (W)</b> [1 W = 1 J s<sup>-1</sup>].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q29: Express 1 Kilowatt-hour (1 kWh) of electrical energy in standard SI units (Joules).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1 kWh = 1 kW &times; 1 hour = 1000 W &times; 3600 s = <b>3.6 &times; 10<sup>6</sup> Joules (3.6 MJ)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q30: State Joule's Law of Heating for a resistor.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The heat (H) generated in a conductor of resistance R carrying current I for time t is directly proportional to: (1) square of current (I<sup>2</sup>), (2) resistance (R), and (3) time (t): <b>H = I<sup>2</sup> R t Joules</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q31: Between two bulbs rated (220 V, 60 W) and (220 V, 100 W), which bulb has higher filament resistance?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Since resistance R = V<sup>2</sup> / P, resistance is inversely proportional to rated power (R &prop; 1/P). Therefore, the <b>60 W bulb has higher filament resistance</b> [R<sub>60</sub> &approx; 807 &Omega; vs R<sub>100</sub> &approx; 484 &Omega;].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q32: Define Electromotive Force (EMF, &#949;) of an electrochemical cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">EMF of a cell is the maximum potential difference between its two terminals when the cell is in an <b>open circuit</b> (drawing zero external current, I = 0): &#949; = dW / dq. SI Unit: <b>Volt (V)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q33: State the dimensional formula of EMF of a cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">[&#949;] = [Work / Charge] = [M L<sup>2</sup> T<sup>-2</sup>] / [A T] = <b>[M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>]</b> (identical to electric potential).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q34: Define internal resistance of a primary electrochemical cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Internal resistance (r) is the electrical resistance offered by the chemical electrolyte and electrodes inside the cell to the flow of internal ionic current.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q35: State the physical condition under which the terminal potential difference V of a cell is strictly equal to its EMF &#949;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When the circuit is <b>open</b> (no current is drawn from the cell, I = 0) or when the internal resistance of the cell is strictly zero (ideal cell).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q36: Can the terminal potential difference across a cell ever exceed its EMF? If yes, under what condition?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Yes</b>, when the cell is being <b>charged</b> by an external DC source. During charging, current enters the positive terminal and <b>V = &#949; + I r</b> (V &gt; &#949;).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q37: What is the terminal potential difference and current when a cell of EMF &#949; and internal resistance r is short-circuited (R = 0)?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Terminal potential difference <b>V = 0</b>; Short-circuit current reaches maximum value: <b>I<sub>max</sub> = &#949; / r</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q38: State Kirchhoff's Junction Rule (KCL) and name the universal conservation law on which it is based.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">At any circuit node or junction, the algebraic sum of currents entering and leaving is strictly zero: <b>&Sigma; I = 0</b>. It is based on the <b>Law of Conservation of Electric Charge</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q39: State Kirchhoff's Loop Rule (KVL) and name the universal conservation law on which it is based.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The algebraic sum of changes in potential around any closed mesh loop in an electrical network is zero: <b>&Sigma; &Delta;V = 0 (&Sigma; &#949; = &Sigma; I R)</b>. It is based on the <b>Law of Conservation of Energy</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q40: State the mathematical balance condition for a Wheatstone bridge consisting of resistors P, Q, R, and S.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When the galvanometer shows null deflection (zero current I<sub>g</sub> = 0), the bridge is balanced: <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P</span><span style=\"padding: 0 2px; display: inline-block;\">Q</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">S</span></span></b>.</div>\n    </div>\n  </div>\n<h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 35px; margin-bottom: 20px;\">SECTION B: Short Answer Questions (2 &amp; 3 Marks Each) — Q41 to Q80</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q41: Derive the expression for drift velocity of free electrons in terms of relaxation time: v<sub>d</sub> = (e E &#964;) / m.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let an electron experience electric field <b>E</b>. Force <b>F</b> = -e <b>E</b>, acceleration <b>a</b> = -e <b>E</b> / m.<br>If thermal velocity after last collision is <b>u<sub>i</sub></b> and time elapsed is t<sub>i</sub>, velocity <b>v<sub>i</sub></b> = <b>u<sub>i</sub></b> + <b>a</b> t<sub>i</sub>.<br>Taking average over N electrons: <b>v<sub>d</sub></b> = (1/N)&Sigma;<b>v<sub>i</sub></b> = (1/N)&Sigma;<b>u<sub>i</sub></b> + <b>a</b> [(1/N)&Sigma;t<sub>i</sub>].<br>Since average thermal velocity (1/N)&Sigma;<b>u<sub>i</sub></b> = 0 and average time is relaxation time &#964;, we get <b><b>v<sub>d</sub></b> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e <b>E</b> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>. Magnitude: <b>v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q42: Derive the relation between macroscopic electric current I and microscopic drift velocity v<sub>d</sub>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Consider a conductor of length L, cross-sectional area A, with free electron density n.<br>Total volume = A L. Total number of free electrons = n A L.<br>Total charge contained = q = (n A L) e.<br>Time taken by electrons to drift across length L is t = L / v<sub>d</sub>.<br>Current <b>I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span><span style=\"padding: 0 2px; display: inline-block;\">t</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(n A L) e</span><span style=\"padding: 0 2px; display: inline-block;\">L / v<sub>d</sub></span></span> = n e A v<sub>d</sub></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q43: Derive the relation between current density <b>j</b>, conductivity &#963;, and electric field <b>E</b>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Using I = n e A v<sub>d</sub>, current density j = I / A = n e v<sub>d</sub>.<br>Substitute v<sub>d</sub> = (e E &#964;) / m:<br>j = n e [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span>] E.<br>Since electrical conductivity &#963; = (n e<sup>2</sup> &#964;) / m, we get <b>j = &#963; E</b> (or <b>E = &#961; j</b>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q44: Why does an electric bulb glow almost instantaneously when switched on, even though drift velocity of electrons is only ~10<sup>-4</sup> m s<sup>-1</sup>?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When the circuit switch is closed, an electromagnetic field is set up across the entire circuit almost instantaneously at the speed of light (c &approx; 3 &times; 10<sup>8</sup> m s<sup>-1</sup>). Free electrons throughout the entire length of the wire, including the filament, begin drifting simultaneously at the very same instant, lighting the bulb immediately.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q45: A wire of resistance R is stretched uniformly such that its length is doubled. Find its new resistance and resistivity.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Resistivity:</b> Resistivity &#961; is an intrinsic material property and remains <b>strictly unchanged (&#961;' = &#961;)</b>.<br>2. <b>Resistance:</b> When stretched to L' = 2 L, volume V = A L remains constant &rArr; A' = A / 2.<br>New resistance R' = &#961; L' / A' = &#961; (2 L) / (A / 2) = 4 (&#961; L / A) = <b>4 R</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q46: A wire of resistance 16 &Omega; is stretched uniformly until its radius is halved. Find its new resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When radius r' = r / 2, area A' = &pi;(r/2)<sup>2</sup> = A / 4.<br>Since volume V = A L = constant, length becomes L' = 4 L.<br>New resistance R' = &#961; L' / A' = &#961; (4 L) / (A / 4) = 16 (&#961; L / A) = 16 R = 16 &times; 16 = <b>256 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q47: Calculate the relaxation time in copper if electron density is 8.5 &times; 10<sup>28</sup> m<sup>-3</sup> and resistivity is 1.7 &times; 10<sup>-8</sup> &Omega; m. (m = 9.1 &times; 10<sup>-31</sup> kg, e = 1.6 &times; 10<sup>-19</sup> C).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Using &#961; = m / (n e<sup>2</sup> &#964;) &rArr; &#964; = m / (n e<sup>2</sup> &#961;):<br>&#964; = (9.1 &times; 10<sup>-31</sup>) / [(8.5 &times; 10<sup>28</sup>) &times; (1.6 &times; 10<sup>-19</sup>)<sup>2</sup> &times; (1.7 &times; 10<sup>-8</sup>)]<br>&#964; = (9.1 &times; 10<sup>-31</sup>) / [8.5 &times; 10<sup>28</sup> &times; 2.56 &times; 10<sup>-38</sup> &times; 1.7 &times; 10<sup>-8</sup>]<br>&#964; = (9.1 &times; 10<sup>-31</sup>) / (3.70 &times; 10<sup>-17</sup>) = <b>2.46 &times; 10<sup>-14</sup> s</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q48: Explain the physical cause of electrical resistance in metallic conductors on the basis of electron collisions.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When an electric field is applied, free electrons accelerate and gain kinetic energy. However, during their drift, they continually collide with the heavy positive metal ions vibrating in the crystal lattice. In each collision, electrons lose their directed drift kinetic energy to the lattice as thermal vibrational energy. This continuous opposition and momentum transfer due to collisions constitutes electrical resistance.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q49: Deduce the formula for electrical resistivity in terms of electron mass, charge, density, and relaxation time: &#961; = m / (n e<sup>2</sup> &#964;).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">From drift theory, I = n e A v<sub>d</sub> = n e A [(e V &#964;) / (m L)] = [(n e<sup>2</sup> &#964; A) / (m L)] V.<br>Rearranging: V / I = [m / (n e<sup>2</sup> &#964;)] (L / A).<br>Comparing with Ohm's law R = V / I = &#961; (L / A), we obtain: <b>&#961; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q50: Sketch and explain the resistivity vs temperature (&#961; vs T) graphs for: (a) Copper (metal), (b) Silicon (semiconductor), (c) Nichrome (alloy).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Copper (Metal):</b> &#961; increases with T (non-linear at low T, linear at room T) as lattice collisions reduce &#964;.<br>2. <b>Silicon (Semiconductor):</b> &#961; decreases exponentially with T as thermal energy generates abundant electron-hole pairs.<br>3. <b>Nichrome (Alloy):</b> &#961; is high with very weak linear positive slope (&alpha; is very small).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q51: The resistance of a platinum wire is 5.00 &Omega; at 0 &deg;C and 5.79 &Omega; at 100 &deg;C. When inserted in a hot bath, resistance is 6.15 &Omega;. Find bath temperature.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Temperature coefficient &alpha; = (R<sub>100</sub> - R<sub>0</sub>) / (R<sub>0</sub> &times; 100) = (5.79 - 5.00) / (5.00 &times; 100) = 0.79 / 500 = 1.58 &times; 10<sup>-3</sup> &deg;C<sup>-1</sup>.<br>For bath temperature t: t = [(R<sub>t</sub> - R<sub>0</sub>) / (R<sub>0</sub> &alpha;)] = (6.15 - 5.00) / (5.00 &times; 1.58 &times; 10<sup>-3</sup>) = 1.15 / (7.90 &times; 10<sup>-3</sup>) = <b>145.57 &deg;C &approx; 145.6 &deg;C</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q52: Distinguish clearly between Ohmic and Non-Ohmic conductors with illustrative examples and graphs.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Ohmic Conductors:</b> Obey V = I R strictly. V-I graph is a straight line through origin with constant slope (e.g. Copper wire, metals).<br>2. <b>Non-Ohmic Conductors:</b> Violate V = I R. V-I graph is non-linear, non-symmetrical, or possesses negative slope regions (e.g. P-N junction diode, vacuum tube, GaAs, thyristor).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q53: In a forward-biased p-n junction diode, a voltage change from 0.70 V to 0.75 V increases current from 10 mA to 35 mA. Calculate dynamic resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">&Delta;V = 0.75 V - 0.70 V = 0.05 V.<br>&Delta;I = 35 mA - 10 mA = 25 mA = 25 &times; 10<sup>-3</sup> A = 0.025 A.<br>Dynamic resistance <b>r<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&Delta;V</span><span style=\"padding: 0 2px; display: inline-block;\">&Delta;I</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">0.05 V</span><span style=\"padding: 0 2px; display: inline-block;\">0.025 A</span></span> = 2.0 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q54: Explain why electrical power is transmitted over long distances from generating stations at extremely high voltages.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let power to be transmitted be P at voltage V through transmission cables of resistance R<sub>c</sub>.<br>Current in line I = P / V.<br>Power lost as heat in transmission line: <b>P<sub>loss</sub> = I<sup>2</sup> R<sub>c</sub> = (P / V)<sup>2</sup> R<sub>c</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P<sup>2</sup> R<sub>c</sub></span><span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span></span></b>.<br>Since P<sub>loss</sub> &prop; 1/V<sup>2</sup>, transmitting at ultra-high voltages dramatically minimizes I<sup>2</sup> R heat losses and conductor thickness required.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q55: Two bulbs rated (220 V, 40 W) and (220 V, 100 W) are connected in series to 220 V supply. Which bulb glows brighter and why?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Filament resistance R = V<sup>2</sup> / P. R<sub>40</sub> = (220)<sup>2</sup> / 40 = 1210 &Omega;; R<sub>100</sub> = (220)<sup>2</sup> / 100 = 484 &Omega;.<br>In series, current I is same for both. Power consumed P = I<sup>2</sup> R &prop; R.<br>Since R<sub>40</sub> &gt; R<sub>100</sub>, the <b>40 W bulb dissipates more power and glows brighter</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q56: Two bulbs rated (220 V, 40 W) and (220 V, 100 W) are connected in parallel to 220 V supply. Which bulb glows brighter and why?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">In parallel, voltage V = 220 V is identical across both bulbs.<br>Power consumed P = V<sup>2</sup> / R &prop; 1/R &prop; P<sub>rated</sub>.<br>Since 100 W bulb has lower resistance (R<sub>100</sub> = 484 &Omega; vs R<sub>40</sub> = 1210 &Omega;), the <b>100 W bulb dissipates 100 W and glows brighter</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q57: An electric kettle has two heating coils. One boils water in 10 minutes, the other in 15 minutes. Find boiling time if connected in: (a) series, (b) parallel.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let heat required be H at voltage V. H = (V<sup>2</sup>/R<sub>1</sub>) t<sub>1</sub> &rArr; R<sub>1</sub> = V<sup>2</sup> t<sub>1</sub> / H; R<sub>2</sub> = V<sup>2</sup> t<sub>2</sub> / H.<br><b>(a) Series:</b> R<sub>s</sub> = R<sub>1</sub> + R<sub>2</sub> &rArr; <b>t<sub>s</sub> = t<sub>1</sub> + t<sub>2</sub> = 10 + 15 = 25 minutes</b>.<br><b>(b) Parallel:</b> 1/R<sub>p</sub> = 1/R<sub>1</sub> + 1/R<sub>2</sub> &rArr; <b>t<sub>p</sub> = (t<sub>1</sub> t<sub>2</sub>) / (t<sub>1</sub> + t<sub>2</sub>) = (10 &times; 15) / (10 + 15) = 150 / 25 = 6 minutes</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q58: State any four distinct points of difference between Electromotive Force (EMF) and Terminal Potential Difference of a cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Definition:</b> EMF is max work done across entire circuit; PD is work done between two circuit points.<br>2. <b>Circuit Condition:</b> EMF measured in open circuit (I=0); PD measured in closed circuit (I&gt;0).<br>3. <b>Load Dependence:</b> EMF is independent of load R; PD depends directly on R.<br>4. <b>Magnitude:</b> EMF &gt; PD during discharge (V = &#949; - I r).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q59: State the factors upon which the internal resistance of an electrochemical cell depends.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Electrode Separation (d):</b> r &prop; d (increases with distance between plates).<br>2. <b>Electrode Area (A):</b> r &prop; 1/A (decreases with larger immersed surface area).<br>3. <b>Electrolyte Concentration (C):</b> r increases with higher concentration.<br>4. <b>Temperature (T):</b> r decreases as temperature increases (increases ionic mobility).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q60: For a cell of EMF &#949; and internal resistance r, sketch: (a) V vs R graph, (b) V vs I graph.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>V vs R Graph:</b> V = &#949; R / (R + r). Starts from origin (0,0), curves upwards and asymptotically approaches V = &#949; as R &rarr; &infin;.<br>2. <b>V vs I Graph:</b> V = &#949; - I r. Straight line with negative slope (-r) having y-intercept &#949; (at I=0) and x-intercept I<sub>sc</sub> = &#949;/r (at V=0).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q61: Derive the formula for internal resistance of a cell: r = R [(&#949; / V) - 1].</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let cell of EMF &#949; and internal resistance r be connected across load R.<br>Current I = &#949; / (R + r).<br>Terminal potential difference V = I R &rArr; I = V / R.<br>Equating both: V / R = &#949; / (R + r) &rArr; (R + r) / R = &#949; / V &rArr; 1 + (r / R) = &#949; / V.<br><b>r / R = (&#949; / V) - 1 &nbsp;&rArr;&nbsp; r = R [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;</span><span style=\"padding: 0 2px; display: inline-block;\">V</span></span> - 1]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q62: A battery of EMF 10 V and internal resistance 3 &Omega; is connected to a resistor. If current is 0.5 A, find: (a) external resistance R, (b) terminal voltage V.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) External Resistance R:</b><br>I = &#949; / (R + r) &rArr; 0.5 = 10 / (R + 3) &rArr; R + 3 = 10 / 0.5 = 20 &rArr; <b>R = 17 &Omega;</b>.<br><br><b>(b) Terminal Voltage V:</b><br>V = &#949; - I r = 10 - (0.5 &times; 3) = 10 - 1.5 = <b>8.5 V</b> (or V = I R = 0.5 &times; 17 = 8.5 V).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q63: When a 2 &Omega; resistor is connected to a cell, current is 0.5 A. When a 5 &Omega; resistor is connected, current is 0.25 A. Find EMF and internal resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">From I = &#949; / (R + r):<br>Case 1: &#949; = 0.5 (2 + r) = 1.0 + 0.5 r &nbsp;--- (1)<br>Case 2: &#949; = 0.25 (5 + r) = 1.25 + 0.25 r &nbsp;--- (2)<br>Equating (1) and (2): 1.0 + 0.5 r = 1.25 + 0.25 r &rArr; 0.25 r = 0.25 &rArr; <b>r = 1.0 &Omega;</b>.<br>Substitute r into (1): &#949; = 1.0 + 0.5(1.0) = <b>1.5 V</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q64: State Maximum Power Transfer Theorem and prove that power delivered to load R is maximum when R = r.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Statement:</b> Maximum power is transferred from a source of EMF &#949; and internal resistance r to an external load R when load resistance equals internal resistance (R = r).<br><br><b>Proof:</b> P = I<sup>2</sup> R = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;</span><span style=\"padding: 0 2px; display: inline-block;\">R + r</span></span>]<sup>2</sup> R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup> R</span><span style=\"padding: 0 2px; display: inline-block;\">(R + r)<sup>2</sup></span></span>.<br>For maximum power, dP/dR = 0 &rArr; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">d</span><span style=\"padding: 0 2px; display: inline-block;\">dR</span></span> [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">(R+r)<sup>2</sup></span></span>] = 0 &rArr; (R+r)<sup>2</sup>(1) - R[2(R+r)] = 0 &rArr; (R+r) - 2R = 0 &rArr; <b>R = r</b>.<br>Maximum power value: <b>P<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">4 r</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q65: Two cells of EMFs &#949;<sub>1</sub>, &#949;<sub>2</sub> and internal resistances r<sub>1</sub>, r<sub>2</sub> are connected in series. Find equivalent EMF and internal resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let current I flow through series cells from terminals A to C via B.<br>V<sub>A</sub> - V<sub>B</sub> = &#949;<sub>1</sub> - I r<sub>1</sub>; &nbsp; V<sub>B</sub> - V<sub>C</sub> = &#949;<sub>2</sub> - I r<sub>2</sub>.<br>Total PD V<sub>AC</sub> = (V<sub>A</sub> - V<sub>B</sub>) + (V<sub>B</sub> - V<sub>C</sub>) = (&#949;<sub>1</sub> + &#949;<sub>2</sub>) - I (r<sub>1</sub> + r<sub>2</sub>).<br>Comparing with V<sub>AC</sub> = &#949;<sub>eq</sub> - I r<sub>eq</sub>:<br><b>&#949;<sub>eq</sub> = &#949;<sub>1</sub> + &#949;<sub>2</sub> &nbsp;|&nbsp; r<sub>eq</sub> = r<sub>1</sub> + r<sub>2</sub></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q66: Two cells of EMFs &#949;<sub>1</sub>, &#949;<sub>2</sub> and internal resistances r<sub>1</sub>, r<sub>2</sub> are connected in parallel. Find equivalent EMF and internal resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let total current I = I<sub>1</sub> + I<sub>2</sub>.<br>Terminal voltage V = &#949;<sub>1</sub> - I<sub>1</sub> r<sub>1</sub> &rArr; I<sub>1</sub> = (&#949;<sub>1</sub> - V) / r<sub>1</sub>; &nbsp; I<sub>2</sub> = (&#949;<sub>2</sub> - V) / r<sub>2</sub>.<br>I = [(&#949;<sub>1</sub> - V) / r<sub>1</sub>] + [(&#949;<sub>2</sub> - V) / r<sub>2</sub>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>] - V [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>].<br>Rearranging for V: <b>&#949;<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> r<sub>2</sub> + &#949;<sub>2</sub> r<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span> &nbsp;|&nbsp; r<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">r<sub>1</sub> r<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q67: State the sign convention rules for applying Kirchhoff's Loop Rule (KVL).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Resistor IR drop:</b> When traversing in the direction of assumed loop current, potential drops: <b>&Delta;V = - I R</b>. If traversing opposite to current, potential rises: <b>&Delta;V = + I R</b>.<br>2. <b>EMF Source:</b> When traversing from negative to positive terminal (inside battery), potential rises: <b>&Delta;V = + &#949;</b>. When traversing from positive to negative terminal, potential drops: <b>&Delta;V = - &#949;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q68: Explain how Kirchhoff's First Law and Second Law illustrate universal conservation laws.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>First Law (Junction Rule):</b> Electric charge cannot accumulate indefinitely at a junction in steady state. Rate of charge entering = Rate of charge leaving (&Sigma; I = 0), manifesting <b>Conservation of Charge</b>.<br>2. <b>Second Law (Loop Rule):</b> Electrostatic force is conservative, so work done in taking charge around closed loop is zero (&oint; <b>E</b> &sdot; d<b>l</b> = 0), manifesting <b>Conservation of Energy</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q69: In a bridge circuit, P = 10 &Omega;, Q = 20 &Omega;, R = 15 &Omega;, S = 30 &Omega;. Is the bridge balanced? Find galvanometer current.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Check ratio: P / Q = 10 / 20 = 1/2; &nbsp; R / S = 15 / 30 = 1/2.<br>Since <b>P / Q = R / S = 1/2</b>, the Wheatstone bridge is perfectly balanced.<br>Potential at B equals potential at D (V<sub>B</sub> = V<sub>D</sub>). Current through galvanometer <b>I<sub>g</sub> = 0 A</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q70: State two advantages of null deflection methods (e.g. Wheatstone bridge) over direct deflection methods with ammeters and voltmeters.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. At null point (I<sub>g</sub> = 0), zero current is drawn from the circuit, eliminating loading errors and internal resistance voltage drops.<br>2. The measurement does not depend on galvanometer calibration or scale accuracy, depending only on the accuracy of standard known resistors.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q71: When is a Wheatstone bridge most sensitive? Explain.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">A Wheatstone bridge is most sensitive when all four arm resistances (P, Q, R, S) are nearly equal (of the same order of magnitude). In this condition, a tiny fractional variation in unknown resistance produces the maximum detectable galvanometer deflection.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q72: In a balanced Wheatstone bridge, if the battery and galvanometer are interchanged, does the balance condition remain satisfied? Justify.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Yes, the bridge remains balanced.</b> The battery and galvanometer branches form conjugate arms. Mathematically, P/Q = R/S is algebraically equivalent to P/R = Q/S, which is the balance condition when positions are interchanged.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q73: A uniform wire of resistance 20 &Omega; is bent into a circle. Find effective resistance between two diametrically opposite points.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The two semicircular halves are in parallel. Each half has resistance R<sub>1</sub> = R<sub>2</sub> = 20 / 2 = 10 &Omega;.<br>Effective resistance <b>R<sub>eff</sub> = (R<sub>1</sub> R<sub>2</sub>) / (R<sub>1</sub> + R<sub>2</sub>) = (10 &times; 10) / (10 + 10) = 100 / 20 = 5 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q74: A uniform wire of resistance 12 &Omega; is bent to form an equilateral triangle ABC. Find equivalent resistance between vertices A and B.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Each of the 3 equal sides has resistance 12 / 3 = 4 &Omega;.<br>Between A and B, side AB (4 &Omega;) is in parallel with the series combination of sides AC and CB (4 + 4 = 8 &Omega;).<br><b>R<sub>AB</sub> = (4 &times; 8) / (4 + 8) = 32 / 12 = 8 / 3 &Omega; = 2.67 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q75: A carbon resistor has color bands: Yellow, Violet, Brown, Gold. Determine its resistance value and tolerance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Color values: Yellow = 4, Violet = 7, Multiplier Brown = 10<sup>1</sup>, Tolerance Gold = &plusmn; 5%.<br>Resistance value: <b>R = 47 &times; 10<sup>1</sup> &Omega; &plusmn; 5% = 470 &Omega; &plusmn; 5%</b> [Range: 446.5 &Omega; to 493.5 &Omega;].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q76: A carbon resistor has color bands: Red, Red, Orange, Silver. Determine its resistance value and tolerance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Color values: Red = 2, Red = 2, Multiplier Orange = 10<sup>3</sup>, Tolerance Silver = &plusmn; 10%.<br>Resistance value: <b>R = 22 &times; 10<sup>3</sup> &Omega; &plusmn; 10% = 22 k&Omega; &plusmn; 10%</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q77: Find equivalent resistance between A and B for a bridge having P = 2 &Omega;, Q = 4 &Omega;, R = 4 &Omega;, S = 8 &Omega;, and central resistor 5 &Omega;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Check balance condition: P / Q = 2 / 4 = 1/2; &nbsp; R / S = 4 / 8 = 1/2.<br>Since P / Q = R / S, bridge is balanced. Zero current flows through central 5 &Omega; resistor (it can be removed).<br>Branch ACB = 2 + 4 = 6 &Omega;; Branch ADB = 4 + 8 = 12 &Omega; in parallel.<br><b>R<sub>AB</sub> = (6 &times; 12) / (6 + 12) = 72 / 18 = 4.0 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q78: A 10 m potentiometer wire has resistance 20 &Omega;. It is connected in series with a 6 V battery and 10 &Omega; resistor. Find potential gradient k.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Total circuit resistance R<sub>total</sub> = 20 + 10 = 30 &Omega;.<br>Current in wire I = &#949; / R<sub>total</sub> = 6 / 30 = 0.2 A.<br>Potential drop across wire V<sub>wire</sub> = I &times; R<sub>wire</sub> = 0.2 &times; 20 = 4.0 V.<br>Potential gradient <b>k = V<sub>wire</sub> / L = 4.0 V / 10 m = 0.40 V m<sup>-1</sup> = 0.004 V cm<sup>-1</sup></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q79: State two primary physical reasons why Nichrome alloy is chosen as heating element in electric irons and toasters.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>High Electrical Resistivity:</b> Enables generation of large Joule heat (H &prop; R) in a compact element length.<br>2. <b>High Melting Point & Non-Oxidizing:</b> Does not oxidize or burn even at red-hot temperatures (~1000 &deg;C).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q80: Why are laboratory connecting wires chosen to be made of thick copper with negligible resistance?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Copper has exceptionally high electrical conductivity (low &#961;), and large cross-sectional area A further reduces resistance (R = &#961; L / A &approx; 0). This prevents unwanted potential drops and power loss in external leads during experiments.</div>\n    </div>\n  </div>\n<h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 35px; margin-bottom: 20px;\">SECTION C: Long Answer Derivations &amp; Complex Numericals (5 Marks Each) — Q81 to Q100</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q81: Define drift velocity and relaxation time. Deduce Ohm's law from fundamental electron dynamics and derive formulas for resistivity and conductivity.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Definitions:</b><br>• Drift velocity (v<sub>d</sub>): Constant average velocity acquired by free electrons opposite to applied electric field <b>E</b>.<br>• Relaxation time (&#964;): Average time interval between two successive electron collisions.<br><br><b>2. Derivation of v<sub>d</sub>:</b><br>Acceleration <b>a</b> = -e <b>E</b> / m. Velocity <b>v<sub>i</sub></b> = <b>u<sub>i</sub></b> + <b>a</b> t<sub>i</sub>.<br>Average <b>v<sub>d</sub></b> = (1/N)&Sigma;<b>v<sub>i</sub></b> = (1/N)&Sigma;<b>u<sub>i</sub></b> + <b>a</b> [(1/N)&Sigma;t<sub>i</sub>] = 0 - (e <b>E</b> &#964; / m) = - (e <b>E</b> &#964; / m).<br>Magnitude: <b>v<sub>d</sub> = (e E &#964;) / m = (e V &#964;) / (m L)</b>.<br><br><b>3. Electric Current Expression:</b><br>I = n e A v<sub>d</sub> = n e A [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964; A</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span>] V.<br><br><b>4. Ohm's Law Deduction:</b><br>V / I = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span>] <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span> = Constant = R &rArr; <b>V = I R</b>.<br><br><b>5. Resistivity &amp; Conductivity:</b><br>Comparing with R = &#961; L / A: <b>&#961; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span></b> &nbsp;|&nbsp; <b>&#963; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&#961;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q82: Draw a neat circuit diagram of Wheatstone bridge. Using Kirchhoff's rules, derive the balance condition P / Q = R / S. Explain conjugate arms.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Circuit Setup:</b> Resistors P, Q, R, S form arms AB, BC, AD, DC. Galvanometer G connected across BD, battery &#949; across AC.<br><br><b>2. Applying Kirchhoff's Junction Law:</b><br>At node B: I<sub>1</sub> = I<sub>g</sub> + I<sub>Q</sub> &rArr; I<sub>Q</sub> = I<sub>1</sub> - I<sub>g</sub>.<br>At node D: I<sub>2</sub> + I<sub>g</sub> = I<sub>S</sub> &rArr; I<sub>S</sub> = I<sub>2</sub> + I<sub>g</sub>.<br><br><b>3. Applying Kirchhoff's Loop Law:</b><br>• Mesh ABDA: - I<sub>1</sub> P - I<sub>g</sub> G + I<sub>2</sub> R = 0 &rArr; I<sub>1</sub> P + I<sub>g</sub> G = I<sub>2</sub> R &nbsp;--- (1)<br>• Mesh BCDB: - (I<sub>1</sub> - I<sub>g</sub>) Q + (I<sub>2</sub> + I<sub>g</sub>) S + I<sub>g</sub> G = 0 &nbsp;--- (2)<br><br><b>4. Null Deflection Condition (I<sub>g</sub> = 0):</b><br>When V<sub>B</sub> = V<sub>D</sub>, I<sub>g</sub> = 0.<br>From (1): I<sub>1</sub> P = I<sub>2</sub> R.<br>From (2): I<sub>1</sub> Q = I<sub>2</sub> S.<br>Dividing: (I<sub>1</sub> P) / (I<sub>1</sub> Q) = (I<sub>2</sub> R) / (I<sub>2</sub> S) &rArr; <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P</span><span style=\"padding: 0 2px; display: inline-block;\">Q</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">S</span></span></b>.<br><br><b>5. Conjugate Arms:</b> Battery across AC and Galvanometer across BD can be interchanged without changing the null condition because P/Q = R/S is algebraically identical to P/R = Q/S.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q83: Derive expressions for equivalent EMF and internal resistance of two cells connected in parallel. Generalize to n identical cells.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Setup:</b> Two cells of EMFs &#949;<sub>1</sub>, &#949;<sub>2</sub> and internal resistances r<sub>1</sub>, r<sub>2</sub> connected in parallel between points A and B.<br>Let currents supplied be I<sub>1</sub> and I<sub>2</sub> &rArr; Total current I = I<sub>1</sub> + I<sub>2</sub>.<br><br><b>2. Terminal Voltage Formulation:</b><br>V = &#949;<sub>1</sub> - I<sub>1</sub> r<sub>1</sub> &rArr; I<sub>1</sub> = (&#949;<sub>1</sub> - V) / r<sub>1</sub>.<br>V = &#949;<sub>2</sub> - I<sub>2</sub> r<sub>2</sub> &rArr; I<sub>2</sub> = (&#949;<sub>2</sub> - V) / r<sub>2</sub>.<br><br><b>3. Total Current:</b><br>I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> - V</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>2</sub> - V</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span> = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>] - V [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>].<br><br><b>4. Rearranging for V:</b><br>V = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> r<sub>2</sub> + &#949;<sub>2</sub> r<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span> - I [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">r<sub>1</sub> r<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span>].<br>Comparing with V = &#949;<sub>eq</sub> - I r<sub>eq</sub>:<br><b>&#949;<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> r<sub>2</sub> + &#949;<sub>2</sub> r<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span> &nbsp;|&nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>eq</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span></b>.<br><br><b>5. n Identical Cells:</b> For n cells each of EMF &#949; and r: <b>&#949;<sub>eq</sub> = &#949;</b>, &nbsp; <b>r<sub>eq</sub> = r / n</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q84: For mixed grouping of m rows with n cells in each row across load R, derive total current and prove max current occurs when R = n r / m.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Total Number of Cells:</b> N = m &times; n.<br><b>2. Equivalent EMF:</b> Each row has n series cells &rArr; EMF = n &#949;. With m rows in parallel &rArr; <b>&#949;<sub>eq</sub> = n &#949;</b>.<br><b>3. Equivalent Internal Resistance:</b> Each row has resistance n r. With m rows in parallel &rArr; <b>r<sub>eq</sub> = n r / m</b>.<br><b>4. Total Circuit Current:</b><br>I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>eq</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R + r<sub>eq</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">R + (n r / m)</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m n &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">m R + n r</span></span>.<br><br><b>5. Condition for Maximum Current:</b><br>Denominator m R + n r = (&radic;(m R) - &radic;(n r))<sup>2</sup> + 2&radic;(m n R r).<br>Current I is maximum when (&radic;(m R) - &radic;(n r))<sup>2</sup> = 0 &rArr; &radic;(m R) = &radic;(n r) &rArr; m R = n r &rArr; <b>R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n r</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> = r<sub>eq</sub></b>.<br>Max current: <b>I<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">2 R</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">2 r</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q85: In a circuit network, two batteries of 12 V (r=1 &Omega;) and 6 V (r=2 &Omega;) are connected in parallel across load 4 &Omega;. Find branch currents and terminal voltage using Kirchhoff's rules.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Circuit Setup:</b> Node A connects positive terminals. Let battery 1 deliver I<sub>1</sub>, battery 2 deliver I<sub>2</sub>, load current I = I<sub>1</sub> + I<sub>2</sub>.<br><br><b>2. Loop 1 (Battery 1 and Load):</b><br>12 - 1(I<sub>1</sub>) - 4(I<sub>1</sub> + I<sub>2</sub>) = 0 &rArr; 5 I<sub>1</sub> + 4 I<sub>2</sub> = 12 &nbsp;--- (1)<br><br><b>3. Loop 2 (Battery 2 and Load):</b><br>6 - 2(I<sub>2</sub>) - 4(I<sub>1</sub> + I<sub>2</sub>) = 0 &rArr; 4 I<sub>1</sub> + 6 I<sub>2</sub> = 6 &nbsp;&rArr;&nbsp; 2 I<sub>1</sub> + 3 I<sub>2</sub> = 3 &nbsp;--- (2)<br><br><b>4. Solving Simultaneous Equations:</b><br>Multiply (1) by 3: 15 I<sub>1</sub> + 12 I<sub>2</sub> = 36.<br>Multiply (2) by 4: 8 I<sub>1</sub> + 12 I<sub>2</sub> = 12.<br>Subtract: 7 I<sub>1</sub> = 24 &rArr; <b>I<sub>1</sub> = 24 / 7 A &approx; 3.43 A</b>.<br>From (2): 2(24/7) + 3 I<sub>2</sub> = 3 &rArr; 3 I<sub>2</sub> = 3 - 48/7 = -27/7 &rArr; <b>I<sub>2</sub> = -9 / 7 A &approx; -1.29 A</b> (Battery 2 is actually being charged!).<br><br><b>5. Load Current &amp; Voltage:</b><br>I = I<sub>1</sub> + I<sub>2</sub> = 24/7 - 9/7 = <b>15 / 7 A &approx; 2.14 A</b>.<br>Terminal Voltage V = I R = (15/7) &times; 4 = <b>60 / 7 V &approx; 8.57 V</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q86: A heating element connected to 230 V draws initial current 3.2 A settling to 2.8 A. If room temp is 27.0 &deg;C and &alpha; = 1.70 &times; 10<sup>-4</sup> &deg;C<sup>-1</sup>, find steady temperature.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. Resistance at room temp T<sub>0</sub> = 27.0 &deg;C: R<sub>0</sub> = V / I<sub>0</sub> = 230 / 3.2 = 71.875 &Omega;.<br>2. Resistance at steady state T: R<sub>T</sub> = V / I = 230 / 2.8 = 82.143 &Omega;.<br>3. Using R<sub>T</sub> = R<sub>0</sub> [1 + &alpha; (T - T<sub>0</sub>)]:<br>T - T<sub>0</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R<sub>T</sub> - R<sub>0</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>0</sub> &alpha;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">82.143 - 71.875</span><span style=\"padding: 0 2px; display: inline-block;\">71.875 &times; 1.70 &times; 10<sup>-4</sup></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">10.268</span><span style=\"padding: 0 2px; display: inline-block;\">0.01221875</span></span> &approx; 840.3 &deg;C.<br>4. Steady temperature: T = 27.0 + 840.3 = <b>867.3 &deg;C</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q87: Twelve identical resistors each of resistance R form a skeleton cube. Find equivalent resistance across body diagonal corners.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Symmetry &amp; Current Division:</b> Let current 6I enter corner A and leave opposite body diagonal corner G.<br>• At A, current divides equally into 3 edges (AB, AD, AE): current = 2I each.<br>• At nodes B, D, E, each 2I divides into 2 edges: current = I each (6 edges carry I).<br>• At nodes C, F, H, currents recombine into 3 edges leading to G: current = 2I each.<br><br><b>2. Potential Drop along Path A &rarr; B &rarr; C &rarr; G:</b><br>V<sub>AG</sub> = (2I) R + (I) R + (2I) R = 5 I R.<br><br><b>3. Equivalent Resistance:</b><br>Total current entered = 6I.<br>V<sub>AG</sub> = (6I) R<sub>eq</sub> &rArr; 5 I R = 6 I R<sub>eq</sub> &rArr; <b>R<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">5</span><span style=\"padding: 0 2px; display: inline-block;\">6</span></span> R</b>.<br>(For face diagonal corners: R<sub>face</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3</span><span style=\"padding: 0 2px; display: inline-block;\">4</span></span> R; along edge: R<sub>edge</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">7</span><span style=\"padding: 0 2px; display: inline-block;\">12</span></span> R).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q88: Derive power output P(R) for battery (&#949;, r). Prove max power occurs at R = r, find P<sub>max</sub>, and calculate electrical efficiency.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Power Output:</b> Current I = &#949; / (R + r). Power delivered to load P = I<sup>2</sup> R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup> R</span><span style=\"padding: 0 2px; display: inline-block;\">(R + r)<sup>2</sup></span></span>.<br><b>2. Maximization:</b> dP/dR = 0 &rArr; (R+r)<sup>2</sup> - 2R(R+r) = 0 &rArr; <b>R = r</b>.<br><b>3. Maximum Power:</b> <b>P<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup> r</span><span style=\"padding: 0 2px; display: inline-block;\">(2r)<sup>2</sup></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">4 r</span></span></b>.<br><b>4. Electrical Efficiency at P<sub>max</sub>:</b><br>Total power generated by cell P<sub>total</sub> = &#949; I = &#949; [&#949; / 2r] = &#949;<sup>2</sup> / 2r.<br>Efficiency &eta; = P<sub>load</sub> / P<sub>total</sub> = [&#949;<sup>2</sup> / 4r] / [&#949;<sup>2</sup> / 2r] = 1/2 = <b>50%</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q89: A Cu wire (L=2 m, A=10<sup>-6</sup> m<sup>2</sup>, n=8.5 &times; 10<sup>28</sup> m<sup>-3</sup>, &#961;=1.7 &times; 10<sup>-8</sup> &Omega; m) carries 2 A. Find: (a) v<sub>d</sub>, (b) &#964;, (c) E, (d) &#956;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) Drift Velocity:</b> v<sub>d</sub> = I / (n e A) = 2.0 / [(8.5 &times; 10<sup>28</sup>)(1.6 &times; 10<sup>-19</sup>)(10<sup>-6</sup>)] = 2.0 / 1.36 &times; 10<sup>4</sup> = <b>1.47 &times; 10<sup>-4</sup> m s<sup>-1</sup></b>.<br><b>(b) Relaxation Time:</b> &#964; = m / (n e<sup>2</sup> &#961;) = (9.1 &times; 10<sup>-31</sup>) / [(8.5 &times; 10<sup>28</sup>)(1.6 &times; 10<sup>-19</sup>)<sup>2</sup>(1.7 &times; 10<sup>-8</sup>)] = <b>2.46 &times; 10<sup>-14</sup> s</b>.<br><b>(c) Electric Field:</b> E = V / L = (I R) / L = (I &#961; L / A) / L = (I &#961;) / A = (2 &times; 1.7 &times; 10<sup>-8</sup>) / 10<sup>-6</sup> = <b>0.034 V m<sup>-1</sup></b>.<br><b>(d) Mobility:</b> &#956; = v<sub>d</sub> / E = (1.47 &times; 10<sup>-4</sup>) / 0.034 = <b>4.32 &times; 10<sup>-3</sup> m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q90: Discuss deviations from Ohm's law in p-n diodes, thyristors, and GaAs. Explain negative dynamic resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Non-Linearity in P-N Diode:</b> Asymmetric conduction; exponential current rise in forward bias (I &approx; I<sub>0</sub>(e<sup>eV/k<sub>B</sub>T</sup> - 1)) and tiny saturation current in reverse bias.<br>2. <b>Thyristor:</b> Four-layer p-n-p-n device with distinct forward blocking, negative resistance, and high-conduction on states.<br>3. <b>Negative Dynamic Resistance in GaAs:</b> Due to transfer of electrons from high-mobility lower energy valley to low-mobility upper energy conduction valley at threshold fields (~3 kV/cm). In this region, dI/dV &lt; 0. Utilized in Gunn diode microwave oscillators.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q91: An unbalanced bridge has P=1 &Omega;, Q=2 &Omega;, R=2 &Omega;, S=4 &Omega;, and galvanometer G=5 &Omega; across BD, battery 2 V across AC. Find branch currents.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Using loop analysis with loop currents I<sub>1</sub> (mesh ABDA) and I<sub>2</sub> (mesh BCDB):<br>P=1 &Omega;, Q=2 &Omega;, R=2 &Omega;, S=4 &Omega;. Notice P/Q = 1/2 and R/S = 2/4 = 1/2!<br>Here P/Q = R/S = 1/2, so the bridge is actually <b>BALANCED</b>!<br>Current through galvanometer <b>I<sub>g</sub> = 0 A</b>.<br>Arm ACB resistance = 1 + 2 = 3 &Omega; &rArr; I<sub>ACB</sub> = 2 V / 3 &Omega; = <b>0.67 A</b>.<br>Arm ADB resistance = 2 + 4 = 6 &Omega; &rArr; I<sub>ADB</sub> = 2 V / 6 &Omega; = <b>0.33 A</b>.<br>Total battery current I = 0.67 + 0.33 = <b>1.0 A</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q92: An electric heater on 220 V draws 10 A to heat 50 kg water from 20 &deg;C to 80 &deg;C at 80% efficiency. Find: (a) resistance, (b) time taken, (c) cost at ₹6.00/kWh.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) Resistance:</b> R = V / I = 220 V / 10 A = <b>22 &Omega;</b>.<br><b>(b) Power &amp; Heat Required:</b><br>Input Power P = V I = 220 &times; 10 = 2200 W = 2.2 kW.<br>Heat required Q = m c &Delta;T = 50 kg &times; 4200 J kg<sup>-1</sup> K<sup>-1</sup> &times; (80 - 20) = 50 &times; 4200 &times; 60 = 12.6 &times; 10<sup>6</sup> J.<br>Useful heat = &eta; &times; P &times; t &rArr; 12.6 &times; 10<sup>6</sup> = 0.80 &times; 2200 &times; t &rArr; 1760 t = 12.6 &times; 10<sup>6</sup> &rArr; <b>t = 7159 s &approx; 1.99 hours</b>.<br><b>(c) Cost of Energy:</b><br>Energy consumed = P &times; t = 2.2 kW &times; 1.9886 h = 4.375 kWh units.<br>Cost = 4.375 &times; ₹6.00 = <b>₹ 26.25</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q93: A cell of EMF 12 V (r=2 &Omega;) is tested under: (a) Open circuit, (b) Load R=10 &Omega;, (c) Charging at 2 A by 16 V source. Find terminal voltage in each case.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) Open Circuit (I = 0):</b><br>V = &#949; = <b>12.0 V</b>.<br><br><b>(b) Connected to Load R = 10 &Omega; (Discharging):</b><br>Current I = &#949; / (R + r) = 12 / (10 + 2) = 1.0 A.<br>Terminal voltage V = &#949; - I r = 12 - (1.0 &times; 2) = <b>10.0 V</b>.<br><br><b>(c) Charging by external source at I = 2.0 A:</b><br>Terminal voltage V = &#949; + I r = 12 + (2.0 &times; 2) = <b>16.0 V</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q94: State the principle of a potentiometer. Why is it preferred over a voltmeter for measuring EMF of a cell?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Principle of Potentiometer:</b> When a steady current flows through a wire of uniform cross-sectional area and composition, the potential drop across any length L of the wire is directly proportional to that length: <b>V &prop; L &rArr; V = k L</b>, where k = V/L is potential gradient.<br><br><b>2. Why preferred over Voltmeter:</b><br>A voltmeter draws a small finite current to show deflection, measuring terminal voltage V = &#949; - Ir (less than true EMF). A potentiometer works on the <b>null deflection method</b> drawing zero current from the test cell at balance point, acting like an ideal voltmeter with infinite resistance to measure the exact true EMF.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q95: Explain with circuit diagram how a potentiometer is used to find internal resistance of a cell. Derive r = R [(l<sub>1</sub> - l<sub>2</sub>) / l<sub>2</sub>].</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Working:</b><br>• With key K open, cell is in open circuit. Null point is obtained at length l<sub>1</sub> &rArr; <b>&#949; = k l<sub>1</sub></b>.<br>• With key K closed across shunt resistor R, current is drawn. Null point shifts to length l<sub>2</sub> &rArr; <b>V = k l<sub>2</sub></b>.<br><br><b>2. Derivation:</b><br>Dividing the two equations: &#949; / V = (k l<sub>1</sub>) / (k l<sub>2</sub>) = l<sub>1</sub> / l<sub>2</sub>.<br>Substitute into internal resistance formula r = R [(&#949;/V) - 1]:<br><b>r = R [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">l<sub>1</sub> - l<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">l<sub>2</sub></span></span>]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q96: Prove that when a wire of resistance R is stretched such that length increases by x% (x <= 5%), resistance increases by 2x%. Solve for length increase of 0.2%.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. Resistance R = &#961; L / A = &#961; L<sup>2</sup> / V (since Volume V = A L = constant).<br>Taking natural log: ln R = ln(&#961;/V) + 2 ln L.<br>Differentiating: &Delta;R / R = 2 (&Delta;L / L).<br>Multiplying by 100: <b>% Change in R = 2 &times; (% Change in L) = 2x%</b>.<br><br>2. For length increase of 0.2%: % increase in R = 2 &times; 0.2% = <b>0.40%</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q97: Derive Joule's heating law H = I<sup>2</sup> R t. Prove transmitting power P over line R<sub>c</sub> at voltage V reduces power loss by 1/V<sup>2</sup>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Derivation of H:</b> Work done in moving charge q through potential difference V is W = V q = V (I t) = (I R) (I t) = <b>I<sup>2</sup> R t Joules</b>.<br><br><b>2. Transmission Power Loss:</b><br>Current transmitted I = P / V.<br>Power lost as heat in line cables P<sub>loss</sub> = I<sup>2</sup> R<sub>c</sub> = (P / V)<sup>2</sup> R<sub>c</sub> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P<sup>2</sup> R<sub>c</sub></span><span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span></span></b>.<br>If transmission voltage is stepped up by a factor of k (V' = k V), power loss becomes P'<sub>loss</sub> = P<sub>loss</sub> / k<sup>2</sup>, dramatically minimizing energy waste.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q98: Find equivalent resistance between A and B for a symmetric 5-resistor bridge network with P=R=2 &Omega;, Q=S=4 &Omega;, and central resistor 10 &Omega;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Check balance ratio: P / Q = 2 / 4 = 1/2; &nbsp; R / S = 2 / 4 = 1/2.<br>Since P/Q = R/S = 1/2, bridge is balanced. Potential at central nodes is equal, zero current flows through 10 &Omega; resistor.<br>Upper branch ACB = 2 + 4 = 6 &Omega;.<br>Lower branch ADB = 2 + 4 = 6 &Omega;.<br>Both branches are in parallel: <b>R<sub>AB</sub> = (6 &times; 6) / (6 + 6) = 36 / 12 = 3.0 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q99: Two heating elements R<sub>1</sub>, R<sub>2</sub> operate on voltage V. Prove ratio of parallel to series heating rates is H<sub>p</sub> / H<sub>s</sub> = (R<sub>1</sub> + R<sub>2</sub>)<sup>2</sup> / (R<sub>1</sub> R<sub>2</sub>) >= 4.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Parallel Rate:</b> H<sub>p</sub> = V<sup>2</sup> / R<sub>p</sub> = V<sup>2</sup> [(R<sub>1</sub> + R<sub>2</sub>) / (R<sub>1</sub> R<sub>2</sub>)].<br><b>2. Series Rate:</b> H<sub>s</sub> = V<sup>2</sup> / R<sub>s</sub> = V<sup>2</sup> / (R<sub>1</sub> + R<sub>2</sub>).<br><b>3. Ratio:</b> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">H<sub>p</sub></span><span style=\"padding: 0 2px; display: inline-block;\">H<sub>s</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sup>2</sup> (R<sub>1</sub> + R<sub>2</sub>) / (R<sub>1</sub> R<sub>2</sub>)</span><span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup> / (R<sub>1</sub> + R<sub>2</sub>)</span></span> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(R<sub>1</sub> + R<sub>2</sub>)<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub> R<sub>2</sub></span></span></b>.<br>Since (R<sub>1</sub> + R<sub>2</sub>)<sup>2</sup> - 4 R<sub>1</sub> R<sub>2</sub> = (R<sub>1</sub> - R<sub>2</sub>)<sup>2</sup> &ge; 0 &rArr; <b>H<sub>p</sub> / H<sub>s</sub> &ge; 4</b> (Minimum ratio = 4 when R<sub>1</sub> = R<sub>2</sub>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(142, 45, 226, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q100: Three batteries &#949;<sub>1</sub>=6 V (1 &Omega;), &#949;<sub>2</sub>=4 V (2 &Omega;), &#949;<sub>3</sub>=2 V (1 &Omega;) are in parallel across load R=5 &Omega;. Find equivalent EMF, internal r, and load current.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Equivalent Internal Resistance:</b><br>1/r<sub>eq</sub> = 1/r<sub>1</sub> + 1/r<sub>2</sub> + 1/r<sub>3</sub> = 1/1 + 1/2 + 1/1 = 2.5 &Omega;<sup>-1</sup> = 5/2 &Omega;<sup>-1</sup> &rArr; <b>r<sub>eq</sub> = 2/5 = 0.40 &Omega;</b>.<br><br><b>2. Equivalent EMF:</b><br>&#949;<sub>eq</sub> / r<sub>eq</sub> = &#949;<sub>1</sub>/r<sub>1</sub> + &#949;<sub>2</sub>/r<sub>2</sub> + &#949;<sub>3</sub>/r<sub>3</sub> = 6/1 + 4/2 + 2/1 = 6 + 2 + 2 = 10 A.<br><b>&#949;<sub>eq</sub> = 10 &times; r<sub>eq</sub> = 10 &times; 0.40 = 4.0 V</b>.<br><br><b>3. Load Current I:</b><br>I = &#949;<sub>eq</sub> / (R + r<sub>eq</sub>) = 4.0 / (5.0 + 0.40) = 4.0 / 5.4 = <b>0.741 A</b>.<br><br><b>4. Terminal Voltage V:</b><br>V = I R = 0.741 &times; 5.0 = <b>3.70 V</b>.</div>\n    </div>\n  </div>\n</div>";

